INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akumajou Dracula X: Gekka no Yasoukyoku', 'As a descendant of Dracula, you must end the vampire bloodline. Can you rid the world of this unspeakable terror? Uncover the mystery of Castlevania and challenge an adventure as legendary as its name. Over 140 different enemies, bosses, and ghastly creatures. Awesome magical spells - transform into a bat, a wolf, or etheral mist. Hidden weapons, secrets, and characters... This game is an expanded version of Castlevania: Symphony of the Night, with additional areas and a new secret playable character.' FROM games WHERE igdb_id = 45508 ON CONFLICT (game_id, language_code) DO NOTHING;
