INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quest 64', 'Celtland has been cast into chaos by the theft of Eletale''s Book. This mystical volume contains the secrets of the Spirit Tamers. Control Brian, a magician''s apprentice, as he explores the expansive countryside and villages on his quest. If he does not reclaim the book, the Kingdom of Celtland will be cast into darkness forever.' FROM games WHERE igdb_id = 3580 ON CONFLICT (game_id, language_code) DO NOTHING;
