INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 2: Dual Shock Ver.', 'First re-release of Resident Evil 2, the Dual Shock Ver. incorporated support for the PlayStation''s DualShock analog controller and vibration functions. Also included is a new unlockable mini-game called "Extreme Battle" and a "Rookie" mode, which allows the player to start the main story with a powerful weapon with infinite ammo.' FROM games WHERE igdb_id = 213875 ON CONFLICT (game_id, language_code) DO NOTHING;
