INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominant Species', 'Enter the bizarre and alien world of Dominant Species- the next generation command and control real time strategy game with fully 3-D creatures and terrain. You are a powerful alien intelligence engaged in constant and deadly conflict with other hives over the possession of Anima, the precious substance that sustains you and your fellow aliens. However, unwelcome humans have arrived on your planet and threaten to upset the balance of conflict between hives that has raged for countless millennia. Attempting to take the priceless Anima and use it to create immortality, humans join an epic battle of survival of the fittest.' FROM games WHERE igdb_id = 1857 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 1857 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
