INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadlock II: Shrine Wars', 'Deadlock II: Shrine Wars is an exciting game of strategy, resource management and military conquest. Each race has its own strengths and weaknesses - learn to exploit them to your advantage. Build, trade, research, attack, as you search for the ancient knowledge that will grant you ultimate control over the entire Universe.' FROM games WHERE igdb_id = 10172 ON CONFLICT (game_id, language_code) DO NOTHING;
