INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal', 'Your prison ship has crash-landed on the fastest, sleekest, most dangerous 3D world ever created. Look around, crystal clear water shimmers, shadows dance and shift, alien architecture fades into the horizon. Discover the secret of this mysterious planet and find out what caused a peaceful race to be enslaved by vicious merciless aggressors.' FROM games WHERE igdb_id = 273 ON CONFLICT (game_id, language_code) DO NOTHING;
