INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('love-escalator', 228633, '1998-04-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckafo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Escalator', 'The third high school year is about to begin, and Takashi Kurosaki decides that it should be a memorable year - at least from the point of view of romantic adventures. His best friend asks Takashi to help him win the heart of Rie, a girl whom Takashi liked in junior high school but hasn''t seen much since. However, when Takashi meets Rie, he begins to realize that he may have feelings for her, and is torn between friendship and romance. Love Escalator is a visual novel with light dating simulation elements. Most of the game consists of anime-style pictures accompanied by text. The game is divided into days; every day, the player can choose dating activities for the protagonist. There are three main heroines, and the player can choose which one to take on a date. Depending on the concrete choice of activities, the girl''s fondness of the protagonist will increase or decrease. It is possible to go to cinema, art gallery, bar, or a "love hotel", where the girl may agree to have sex with the protagonist if she likes him well enough. Most of the explicit sex scenes offer additional menu-based interactivity (choice of sexual positions) and are animated.' FROM games WHERE igdb_id = 228633 ON CONFLICT (game_id, language_code) DO NOTHING;
