INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outwars', 'Outwars is a science fiction third-person shooter developed by SingleTrac and published by Microsoft in 1998. The game also features an 8-player multiplayer mode allowing players to compete with and against one another in the modes: Free for All, Assassin, Smear the cyborg, Team War, Team Mission, and Capture the flag. A rather unusual feature of Outwars is that the legs and the torso can be controlled separately. This extra function can however be disabled by reconfiguring the controls.' FROM games WHERE igdb_id = 57676 ON CONFLICT (game_id, language_code) DO NOTHING;
