INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shuujin-he-no-pert-em-hru', 146169, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yf9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9d7t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shuujin he no Pert-em-Hru', 'Shuujin he no Pert-em-Hru is a Japanese freeware role-playing video game created with RPG Maker Dante 98 II, by Makoto Yaotani. "Pert-em-Hru" refers to the Egyptian Book of the Dead, so the title of the game means "The Book of the Dead for the Prisoners". The game was produced by two people, with Yaotani responsible for most of the development, and production took a year and a half to complete. The game received many honours, including the Platinum Prize in the ASCII-held monthly contest "Internet Contest Park" — the only Platinum Prize to be given out during the existence of the contest. A remake version utilizing RPG Maker VX is currently under development since 2012, 14 years after the release of the original.' FROM games WHERE igdb_id = 146169 ON CONFLICT (game_id, language_code) DO NOTHING;
