INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla Online', 'Godzilla Online was a multiplayer only game based on the 1998 film "Godzilla" from Centropolis Entertainment. Players assumed the role of the Soldier, Scientist, Baby Godzilla, or Reporter and competed in various match types in arenas that were similar to locations in the movie; gaining EXP to progress through ranks.' FROM games WHERE igdb_id = 72723 ON CONFLICT (game_id, language_code) DO NOTHING;
