INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autobahn Raser', 'Autobahn Raser is the second release in Davilex''s Racer series and the first in the Autobahn Raser series. While their previous game A2 Racer took place on the Dutch A2 highway this one is set to the German Autobahn. You''ll participate in various races across various parts of the German Autobahn and connected cities.' FROM games WHERE igdb_id = 210275 ON CONFLICT (game_id, language_code) DO NOTHING;
