INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jissen-pachi-slot-hisshouhou-sammy-revolution', 382841, '1998-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob45o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4z6u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jissen Pachi-Slot Hisshouhou! Sammy Revolution', 'Jissen Pachi-Slot Hisshouhou! - Sammy Revolution (aka Pachisuro! Sammy Revolution) is a pachi-slot (gambling machine) game that features a perfect recreation of 5 gambling machines (Ultraman Club 3, Matsuri, Tequila, Haunted Party 2 & BC20000) with different levels of zoom. A slot machine (American English), fruit machine (British English), poker machine (Australian English) or simply slot (American English) is a casino gambling machine with three or more reels which spin when a button is pushed. Slot machines are also known as one-armed bandits because slot machines were originally operated by a lever on the side of the machine (the one arm) instead of a button on the front panel, and because of their ability to leave the gamer penniless. Many modern machines still have a legacy lever in addition to the button. Slot machines include a currency detector that validates the coin or money inserted to play. The machine pays off based on patterns of symbols visible on the front of the machine when it stops. Modern computer technology has resulted in many variations on the slot machine concept. Slot machines are the most popular gambling method in casinos and constitute about 70 percent of the average casino''s income. It is estimated that thirty percent or more of the profits from gambling machines come from problem gamblers.' FROM games WHERE igdb_id = 382841 ON CONFLICT (game_id, language_code) DO NOTHING;
