INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Bout Garou Densetsu Special: Dominated Mind', 'In Real Bout Garou Densetsu Special: Dominated Mind Geese sports a halo over his head. The game comes with a Fan Collection disk consisting of interviews with Fatal Fury characters. The story centers around White''s brainwashing of Billy Kane and attempted takeover of Southtown''s underworld in the power vacuum left by Geese Howard''s death in the original Real Bout.' FROM games WHERE igdb_id = 43874 ON CONFLICT (game_id, language_code) DO NOTHING;
