INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-3rdmix', 94745, '1998-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c1u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dk9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania 3rdMix', 'Beatmania 3rdMix is a rhythm game developed by Konami. It is the third game in the beatmania series and is part of the BEMANI franchise ( which it was named after: BEatMANIa ). It is the only beatmania arcade to have an official European release. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. Beatmania 3rdMix is the first game in the series to introduce combo count, meaning that your current combo is shown while playing and a good or less break your combo. If you get more than 10 combo your great verdicts will start flashing, but it does not award you with any bonuses. Normal and Easy mode has been added to the game, which differs in what songs can be chosen and when. Battle, Mirror and Random modifiers were added. The game features 11 songs from beatmania and beatmania 2ndMIX along with 16 new songs for a total of 27 songs.' FROM games WHERE igdb_id = 94745 ON CONFLICT (game_id, language_code) DO NOTHING;
