INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-mahjong-kiwame-plus-ii', 97877, '1998-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaat8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3uwf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Mahjong Kiwame Plus II', 'Pro Mahjong Kiwame Plus II is a mahjong game and is the second game in the series released for the Playstation One console. The game features 16 different real mahjong players as opponents and the game mode is a 4 player vs mahjong. The game got 3 game modes: Professional, Gamble & Training. Mahjong is a game for four players that originated in China. It was called, meaning sparrow in ancient China, which is still the name most commonly used in some southern Chinese dialects such as Cantonese and Minnan, as well as in Japanese. However, most Mandarin-speaking Chinese now call the game má jiàng. Mahjong involves skill, strategy, and calculation, as well as a certain degree of luck (depending on the variation played, luck can be anything from a minor to a dominant factor in winning). In Asia, mahjong is also popularly played as a gambling game. In the game, each player is dealt either thirteen or sixteen tiles in a hand, depending on the variation being played. On their turn, players draw a tile and discard one, with the goal of making four or five melds (also depending on the variation) and one pair, or "head". Winning comes "on the draw" by drawing a new or discarded tile that completes the hand. Thus, a winning hand actually contains fourteen (or seventeen) tiles.' FROM games WHERE igdb_id = 97877 ON CONFLICT (game_id, language_code) DO NOTHING;
