INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('goryuujin-electro', 384780, '1998-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob8zf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar52ny.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goryuujin Electro', '"GORYUZIN ELECTRO" is a board game acknowledged for its quality by the Good Toy Committee in Japan in 1997. Based on the legend of the dragon, you have to compete connecting special frames and see to what extend can you proceed into your opponent''s territory. No matter how many times you play, it is a fun game for everyone. The gameplay is difficult to explain, the goal of the game is to use all of the player pieces or use the ones that the player needs to reach to other part of the board, (for example the player starts in the bottom of the screen and have to reach the top) the harder part is to that before the opponent do it, both players compete to use their pieces to create obstacles that avoid the opponent to reach the other side, using the opening (that is too the closing piece) to close the line and get a point (or more depending of the pieces used). The game got a challenging gameplay but the difficulty level is really hard.' FROM games WHERE igdb_id = 384780 ON CONFLICT (game_id, language_code) DO NOTHING;
