INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectral Force 2', 'The sequel to Spectral Force is set in a fantasy world called Neverland. The ruler of Demon Kingdom was defeated by the hero Chiffon, leaving behind a son and a daughter, the children of his human wife. The two half-demons strive to regain the lost power. The sister Hiro re-builds the Demon Kingdom, while the brother Jadou finds a way to communicate with our world, and summons a Japanese schoolgirl who soon becomes a mighty warrior under his guidance.' FROM games WHERE igdb_id = 80134 ON CONFLICT (game_id, language_code) DO NOTHING;
