INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gravity-angels-part-4-death-force', 229361, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x17.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckcrk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Angels Part 4: Death Force', 'This is the fourth and final chapter in Brilliant Digital Entertainment''s Gravity Angels series of Multipath Movies. Each one of these interactive movies uses a proprietary video engine that renders animated scenes in real-time. In the course of the movie, players can make a number of ''decisions'' that will lead the story down different plot branches. After the events of the first, second and third chapters, the enigmatic alien ship breaches the surface of Ganymede. Our heroes decide to pay another visit and stumble upon the ship''s control room, where they will make a startling discovery. Time is running out for the team as they find out that Miller Western, the most powerful company in human history, knew all along what was going on on Ganymede. Company reinforcements arrive in strength and they have no intention of taking prisoners. The only thing left to do for Ty, Felice, Jazz, Reece, Bennett and the others, is to start making preparations for their last stand against this Death Force...' FROM games WHERE igdb_id = 229361 ON CONFLICT (game_id, language_code) DO NOTHING;
