INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexplore', 'The game features over 200 levels with puzzle-solving and combat, and allows up to 4 players in cooperative multiplayer mode. The game''s engine utilises voxels for creating 3-D shapes and the level, being then relatively fast at the time it was released. The game world is seen from a top-down, isometric perspective, and the player is allowed to rotate the camera round the centre of view.' FROM games WHERE igdb_id = 8310 ON CONFLICT (game_id, language_code) DO NOTHING;
