INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit''s Math Ages 6-9', 'Reader Rabbit joins his pal Sam the Lion who has entered his dilapidated sailboat in a boat race when a tremendous storm ensues, shipwrecking them on Pirate Island with their boat in pieces. There they meet Penelope the Parrot who encourages Sam and Reader to build a new boat. Play as Reader Rabbit as he solves math puzzles to collect Boat Pieces, but watch out! The Pirats will do anything to stop Sam and Reader.' FROM games WHERE igdb_id = 209739 ON CONFLICT (game_id, language_code) DO NOTHING;
