INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bass Master Classic: Tournament Edition', 'Bass Masters Classic: Tournament Edition is a fishing simulation which, when it was released, billed itself as the only completely 3D fishing game. There are many different ways to play this game. Apart from the tutorial mode there is the Single Player mode which offers the Amateur game, the Professional game, the Arcade game and the Practice game.* In the Amateur game the player fishes a series of one day tournaments under Bass Fishing rules where only the weight of four fish count.' FROM games WHERE igdb_id = 145779 ON CONFLICT (game_id, language_code) DO NOTHING;
