INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA 2: Power Edition', 'Daytona USA 2: Power Edition is a updated re-release of Daytona USA 2: Battle on the Edge, which is the original game with a few changes: It changes the look of the beginners track back to a classic "Oval racetrack", and adds a new "Challenge" track that combines the previous four tracks into a long sprint. It also adds a secret "Specialist Only" Hornet car with a code, which allows players to customize the original Daytona USA Hornet to their specifications. The game saw no home ports, only appearing in "Like a Dragon Gaiden: The Man Who Erased His Name" as "Sega Racing Classic 2".' FROM games WHERE igdb_id = 349356 ON CONFLICT (game_id, language_code) DO NOTHING;
