INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titanic: A Mysterious Undersea Adventure', 'Apparently recent scientific observations near the wreck of the Titanic have revealed the presence of a mysterious undersea village which may have special mystical powers. Discovering an amulet nearby, you dive down to the village to uncover its secret and find out if it played a part in the sinking of the Titanic.' FROM games WHERE igdb_id = 70783 ON CONFLICT (game_id, language_code) DO NOTHING;
