INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heretic II', 'Heretic II is a third-person action game based on the Quake II engine that plunges you into a deep, compelling game combining brutal face-to-face combat and mystery-laden adventure. Gamers travel through complex, richly detailed environments filled with stunning special effects, wicked magic spells, detailed characters, vivid artwork and challenging level designs created by the Raven team and renowned fantasy artist Brom.' FROM games WHERE igdb_id = 20752 ON CONFLICT (game_id, language_code) DO NOTHING;
