INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rogue-trip-vacation-2012', 26143, '1998-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qii.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Trip: Vacation 2012', 'In a world destroyed by pollution, nuclear war and poverty, vacationers have become hot property. They feel the need to escape from their everyday existence and go on vacations! Big Daddy is the vacation king at the moment, and he''s provided some really fabulous getaways for these people. But who''s going to get paid for taking the vacationers to luxurious landmarks and resorts? Well, you are! The "not-right" folks at Singletrac are at it again with Rogue Trip: Vacation 2012, the "spiritual successor" to Twisted Metal 2. In it, you chose one of 16 wacky, down-right sick "automercenaries" and compete with your enemies to pick up the tourists and take them to photo-ops. Doing this gets you lots of money, which can be used buy weapon upgrades and health. But your enemies really don''t want you to have the money -- and they shoot back.' FROM games WHERE igdb_id = 26143 ON CONFLICT (game_id, language_code) DO NOTHING;
