INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elmo Through the Looking-Glass', 'In this game, Elmo goes through the looking-glass in his room to find the little red monster he sees there. Skills emphasized include object identification, visual discrimination, vocabulary, matching, and reading. The game is inspired by Alice Through The Looking-Glass (Alice in Wonderland).' FROM games WHERE igdb_id = 333203 ON CONFLICT (game_id, language_code) DO NOTHING;
