INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kurushi Final: Mental Blocks', 'Bringing a new meaning to the phrase ''mental block'', "Kurushi Final: Mental Blocks" dares you to test your intelligence against a higher power, 9 mind-stretching stages, plus 2-player survival mode, 100 additional challenges and a custom-puzzle generator, "Kurushi Final: Mental Blocks" is a supreme test of mental and physical agility.' FROM games WHERE igdb_id = 43868 ON CONFLICT (game_id, language_code) DO NOTHING;
