INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Furlong 2', 'Final Furlong 2 is a horseracing arcade game which was released by Namco in 1998; it runs on their System 23 hardware, and as the name suggests, it is the sequel to Final Furlong, which was released in the previous year. Players sit in a "saddle" and must rock the cabinet''s horses back and forth, to urge their horses forward, pressing the "Whip" button to speed them up and pulling on "reins" to keep the horse from colliding with the fences or other horses.' FROM games WHERE igdb_id = 355862 ON CONFLICT (game_id, language_code) DO NOTHING;
