INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mia''s Reading Adventure: The Search for Grandma''s Remedy', 'In Mia: The Search for Grandma''s Remedy, players accompany a young mouse on a quest to find a cure for her sick grandmother. Acting as Mia''s guide, children ages five to nine navigate through a series of nine language-based puzzles, each unlocking vital clues that propel the journey forward.' FROM games WHERE igdb_id = 381688 ON CONFLICT (game_id, language_code) DO NOTHING;
