INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('family-bowling', 135648, '1998-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4ln.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3uqk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Bowling', 'Family Bowling (also known as Wai Wai Bowling in a later release) is a bowling game that features 2 courts at the beginning of the game (Prism Town & Liberty Planet), 12 characters (only 4 are available at the beginning of the game) & 2 game modes: - Free or Tournament mode: In this mode there are 4 possible playable characters to choose (Maki, Kazuhiko, Shota & Ichika). The player can select also the number of opponents and if he wants that they will be computer or player opponents. - Challenge Mode: In this mode the characters are the same as in free mode but here the gameplay is about different bowling challenges that the player has to try to clear. The gameplay as usual in the bowling games begins with an overview of the court where the player has to select the direction of the shot, after that the character direction and finally select the power and effect of the shot. At the beginning the player can change the name of the bowler and also select if he want a right-hand or lefty player. The game allows up to four human players (using the same controller, not a multitap) to play at the same game.' FROM games WHERE igdb_id = 135648 ON CONFLICT (game_id, language_code) DO NOTHING;
