INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Queen of Heart ''98', 'The Queen of Heart ''98 is a 2D one-on-one fighting game and the first game in the Queen of Heart series. The player can choose one of 10 female characters and fight against the others. The game features characters from the Leaf visual novel game To Heart. Each girl has her own special moves and unique abilities. It features anime-style graphics and supports multiplayer.' FROM games WHERE igdb_id = 50183 ON CONFLICT (game_id, language_code) DO NOTHING;
