INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit 1st Grade', 'Reader Rabbit: 1st Grade is an educational game for kids between 5 and 7 years old. It teaches elements of language, math, natural sciences, music and art. There is a total of twelve educational activities divided equally among four places that the rabbit protagonist must visit. Four of them are actually puzzles that once solved give access to the locations themselves.' FROM games WHERE igdb_id = 88280 ON CONFLICT (game_id, language_code) DO NOTHING;
