INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Yellow Version: Special Pikachu Edition', 'Pokémon Yellow is an enhanced version of Pokémon Red and Blue that allows you to start the game with your very own Pikachu following you around on-foot and collect the 3 other starters from strangers you meet around the region. However, your goal remains the same: catch them all and become the ultimate Pokémon Master.' FROM games WHERE igdb_id = 1512 ON CONFLICT (game_id, language_code) DO NOTHING;
