INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VS Mahjong: Otome Ryouran', 'A Mahjong game developed by Kaneko where you can play 1V1 Strip-Mahjong as one out of the twelve Japanese high school girls on the roster. Each one participates in a different after-school club. Win any of them on this slightly dishonest arcade to sneak a peek!' FROM games WHERE igdb_id = 310348 ON CONFLICT (game_id, language_code) DO NOTHING;
