INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dokapon! Ikari no Tetsuken', 'Dokapon makes his debut on PlayStation with a board game with RPG elements. The gameplay is the usual board game with a top 2d view and a 3d battle sequences. The battle parts use the usual combat system of a turn based rpg, select the proper action in each turn. When the main enemy of each level is destroyed the game opens other parts of the kingdom.' FROM games WHERE igdb_id = 81411 ON CONFLICT (game_id, language_code) DO NOTHING;
