INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geometry Duel', 'Geometry Duel is a Strategy game which was released in Japan in 1998. The gameplay is a mix between a first person perspective adventure game with good 2d anime characters and a 3d isometric view (with different camera angles) in the battle mode. The battle mode gameplay is the usual tactical rpg, the player put different units and have to defeats the enemy to win.' FROM games WHERE igdb_id = 77709 ON CONFLICT (game_id, language_code) DO NOTHING;
