INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeus: Carnage Heart Second', 'The sequel to Carnage Heart, a mecha action-strategy game from Artdink. Design an unmanned mobile weapon overkill engine, direct the airframe designed by himself and lead the battle to victory. Addition of story part, numerous new aircraft, strengthening of graphics, improvement of operability and completely revamp the system of the previous work. The curtain of dramatic SF simulation set on Jupiter''s satellite rises!' FROM games WHERE igdb_id = 66186 ON CONFLICT (game_id, language_code) DO NOTHING;
