INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 4: The Reversi', 'Reversi (also marketed by Pressman under the trade name Othello) is a board game involving abstract strategy and played by two players on a board with 8 rows and 8 columns and a set of distinct pieces for each side. Pieces typically are disks with a light and a dark face, each side belonging to one player. The player''s goal is to have a majority of their colored pieces showing at the end of the game, turning over as many of their opponent''s pieces as possible.' FROM games WHERE igdb_id = 202997 ON CONFLICT (game_id, language_code) DO NOTHING;
