INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hey-you-pikachu', 2642, '1998-12-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co407c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sca02b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hey You, Pikachu!', 'Hey you, Pokémon fanatic! Have you ever wanted to control your very own Pokémon? Now you can with HEY YOU, PIKACHU! for the Nintendo 64. It''s as simple as speaking into the microphone that connects to your controller. If Pikachu understands you, he''ll respond. The little yellow pocket monster has a vocabulary of approximately 200 words, and Professor Oak is even on hand to train you in the ways of creature communication. Wake up Pikachu each day by shouting "Good Morning!" and decide what games to play and activities to engage in. You can play Pokémon trivia on the in-game TV, gather food, hunt for treasure, collect seemingly endless goodies, go fishing, baby-sit Caterpie, and much more. You''ll also play a variety of mini-games while guiding Pikachu along with friendly commands. As you bond and converse with your cartoon pal you''ll investigate the Ochre Woods, head for the campground, check out Bulbasaur''s picnic, and even solve clever puzzles. HEY YOU, PIKACHU! is an interactive romp that gives the younger set a chance to get up close and personal with their favorite Pokémon character.' FROM games WHERE igdb_id = 2642 ON CONFLICT (game_id, language_code) DO NOTHING;
