INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Milo''s Astro Lanes', 'Have you ever bowled against your buddies with a Nuclear Ball on a lane constructed out of an alien''s tongue? Probably not. But now you can, as you bowl for the perfect game in Milo''s Astro Lanes, the wackiest, most spaced-out bowling blast ever! Use awesome power-ups like the devastating Pea Ball, toxic Cosmic Slime and mighty White Dwarf to thwart your opponents or keep them from stopping you. This insane game is what the future of bowling is all about!' FROM games WHERE igdb_id = 3411 ON CONFLICT (game_id, language_code) DO NOTHING;
