INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fallen Angels', 'Fallen Angels is a two dimensional fighting game that takes a somewhat realistic approach in its gameplay, with super powered moves and with fluid movements animated using real motions (which was also featured in Art of Fighting 3). Projectile attacks are limited to three characters, atypical for the game''s genre. The game featured eight playable characters: Cool, Harry Ness, Yuiren, Yuiran, Tarō, Torao Onigawara, Ruccio Roche and Haiji Mibu. The boss characters are Trigger and Carlos.' FROM games WHERE igdb_id = 39581 ON CONFLICT (game_id, language_code) DO NOTHING;
