INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Centre Court Tennis', 'Centre Court Tennis is a tennis game that does not take itself too seriously. After creating your Lego-like character, you are set to go. The basic game features a multiplayer mode (up to 4 players), a tournament mode and an exhibition mode. You also have four mini-games, "Tennis Court Bingo", "Burning Barrels", "Run and Gun" & Knock''em Down", where your goal is to hit certain objects in the tennis field. You can win special prices for getting enough points.' FROM games WHERE igdb_id = 3456 ON CONFLICT (game_id, language_code) DO NOTHING;
