INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wario Land II', 'What kind of no-good ruffians would break into my castle and steal my treasures?! It''s that rotten Captain Syrup and that Black Sugar Gang! I''m looking out for bad guys and scavenging for coins as I track down my treasures. If I don''t get them all the first time, that''s OK. I can go back again and again until I find them all. Captain Syrup doesn''t stand a chance against me!' FROM games WHERE igdb_id = 1697 ON CONFLICT (game_id, language_code) DO NOTHING;
