INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman IQ Xuànfēng', 'Rockman IQ Xuànfēng (洛克人IQ旋風 "Rockman IQ Whirlwind") is a licensed Mega Man video game released for home computer only in Taiwan by Strawberry Software. Rockman IQ Xuànfēng is a collection of five games. Players can register their names and save high scores, with a leaderboard showing the highest score from each player in each games.' FROM games WHERE igdb_id = 389005 ON CONFLICT (game_id, language_code) DO NOTHING;
