INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Pikachu', 'Pokémon Pikachu, also known as Pocket Pikachu in Japan, is a limited series of two portable Pokémon digital pets (similar to Tamagotchi) featuring the famous yellow electric-type Pokémon, Pikachu. Released on March 27, 1998, in Japan (November 2, 1998, in North America).' FROM games WHERE igdb_id = 194330 ON CONFLICT (game_id, language_code) DO NOTHING;
