INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Football 98', 'World Football 98 is a soccer game, released just before the 1998 Football World Cup. It featured Kiko Narváez, the Spanish national team striker, prominently in the Kiko World Football version. The game was also later distributed as a gift when buying Danone yogurts under the name of Danone World Football where it was an ad game, as in the break between halves advertisements are shown.' FROM games WHERE igdb_id = 260062 ON CONFLICT (game_id, language_code) DO NOTHING;
