INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hana to Ryuu', 'Hana to Ryuu is a yaoi manga series created by Kazuma Kodaka in 1993. Designed as a doujinshi, Hana to Ryu follows Ryuji Kazama, the son of a dead yakuza boss, as he struggles to maintain a peaceful existence while dealing with harmful forces all around him. Hana to Ryu takes place in the universe of another Kodaka series Kizuna, taking place 10-15 years before Kizuna.' FROM games WHERE igdb_id = 352509 ON CONFLICT (game_id, language_code) DO NOTHING;
