INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genocide', 'Genocide is featuring tough and violent gameplay and stereo sound, Genocide pits you against a range of bloody, demonic creatures created using TruLife, delivering the most  disturbingly realistic characters yet seen in a videogame.  In addition, Genocide features an intuitive control method, giving the player complete  360 degree movement freedom; an integrated easy-to-use editor allows you to create,  modify and distribute your own levels and more. Full in-game help is available.' FROM games WHERE igdb_id = 142635 ON CONFLICT (game_id, language_code) DO NOTHING;
