INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Game of Life', 'The classic board game comes to life (no pun intended) on the PC and PlayStation. This is the 1998 Mass Media, Inc. version, and features Full Motion Videos on Enhanced version. Play the Classic or Enhanced version of the classic game. Spin the spinner, get a job, get married, buy a house, play the stock market, take revenge against other players and gain wealth. Play up to 6 players either over a network or the internet.' FROM games WHERE igdb_id = 106271 ON CONFLICT (game_id, language_code) DO NOTHING;
