INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Mario', 'Dr. Mario was remastered for the Super Famicom and released as a stand-alone Nintendo Power service release, only in Japan, and also for the Nintendo Gateway System. The game also received a Satellaview broadcast. The same version was previously bundled with Tetris and released in the West as Tetris & Dr. Mario.' FROM games WHERE igdb_id = 179222 ON CONFLICT (game_id, language_code) DO NOTHING;
