INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duke Nukem: Time to Kill', 'Duke Nukem: Time to Kill is a third-person shooter developed by n-Space for the PlayStation. This is the first 3rd person Duke Nukem game, and has levels in it for 2 player deathmatch. Travel through time in an all-new Duke Nukem frag-fest that gives you more of what you crave! More Duke attitude! More hardcore action! More exploration! More shooter mayhem!' FROM games WHERE igdb_id = 4130 ON CONFLICT (game_id, language_code) DO NOTHING;
