INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-breaker-burst-bishou-o-anata-to', 43816, '1998-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa32s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ts3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Breaker Burst: Bishou o Anata to', 'Blue Breaker Burst is a follow-up to Blue Breaker. However, instead of an RPG, this sequel is a full 3D 1-on-1 fighting game. The main story focuses on a new character named Chimena, though much of the first title''s cast also return. The player moves Chimena around the world map to different locations, where visual novel-style events may occur with other characters, furthering the story and often leading to a fight. Apart from the main "Chimena''s Story", additional stories focusing on other characters are unlocked as the game progresses. There are also a number of other modes. Original Mode is an arcade-style mode that forgoes the story in favor of a string of opponents that must be defeated. Versus mode allows a free battle against the computer or another player, while Training mode lets the player practice moves and combos, and view a moves list for each character.' FROM games WHERE igdb_id = 43816 ON CONFLICT (game_id, language_code) DO NOTHING;
