INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gravity-angels-part-2-the-betrayal', 229359, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x15.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckcq7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Angels Part 2: The Betrayal', 'Gravity Angels Part 2: The Betrayal is the second installment in Brilliant Digital Entertainment''s Gravity Angels saga. Just like the first part, this Multipath Movie uses the in-game engine to render a real-time, three-dimensional, digitally animated story. At certain predetermined points in the storyline the player gets to choose one of multiple plot alternatives or paths that, while influencing the story, never change the actual outcome. Each Multipath Movie episode - they were originally available as Webisodes as well - runs approximately 30 minutes. We rejoin the team of rogue employees, introduced in the first episode, on Jupiter''s moon Ganymede just as the Miller Western Corporate Conglomerate is moving to turn the mining base into a death trap. It soon becomes clear that the company will stop at nothing to secure its interests in the alien artefact discovered deep below the surface. Green, the facility sheriff and company henchman, receives orders to terminate any witnesses. All transmissions are jammed, company backup is on the way and that means there''s only two options left to our heroes: death or a desperate fight for survival.' FROM games WHERE igdb_id = 229359 ON CONFLICT (game_id, language_code) DO NOTHING;
