INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Adventure Rockman', 'Super Adventure Rockman is an interactive movie game and prime spin-off for the classic Mega Man series of video games from Capcom. Its gameplay is a combination of adventure game and shooting game. The game alternates between animated cutscenes, making decisions from a list of text options or arrows, and fighting in a first-person shooter mode.' FROM games WHERE igdb_id = 1732 ON CONFLICT (game_id, language_code) DO NOTHING;
