INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Yume no Owari ni', 'The first game in the Jinguuji Saburo series was released on the NES in 1987. The series told the different cases of a 32 years old detective named Saburo Jinguuji out to solve deadly crimes, that is supported by a cast which includes his assistant Yoko Misoni and local police inspector Sanzo Kumano.' FROM games WHERE igdb_id = 79453 ON CONFLICT (game_id, language_code) DO NOTHING;
