INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('team-losi-rc-racer', 45063, '1998-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9880.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scinhz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Team Losi RC Racer', 'Team Losi RC Racer is a one or two-player racing game that features 16 radio-controlled vehicles. You''ll be racing against various opponents to unlock new tracks (15 in all), discover new cars and conquer the vast hub system that connects every track together. Discovering new tracks and bonus goodies involves locating any given rainbow-colored gate; after you''re familiar with the tracks, you can perfect your times and utilize the gates to your advantage. Of course, you''re not required to race every single time you play -- you can explore the tracks for said gates, finding shortcuts that will give you an advantage over the opposition. Radio-controlled vehicles are based on performance ratings including speed, acceleration, grip and weight. There are four cars to choose from at the start of the game; whereas Krush is average in all areas, the Flame Dragon has incredible handling and acceleration features. Tracks incorporate surreal environments such as beachside raceways, mountainous terrain and a desert.' FROM games WHERE igdb_id = 45063 ON CONFLICT (game_id, language_code) DO NOTHING;
