INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fight 3', 'Final Fight 3 is a pirated port of the SNES game of the same name, made by Hummer Team in 1998. This is Hummer Team''s last game published under J.Y. Company. This is a direct port of the SNES game. All four playable characters from the original game are present, as are most of the enemies, bosses, and rounds. However, the weaker enemies appear throughout the whole game.' FROM games WHERE igdb_id = 223016 ON CONFLICT (game_id, language_code) DO NOTHING;
