INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimCity 2000', 'A Japan-only release of SimCity 2000 for the Nintendo 64 on January 30, 1998, produced and published by Imagineer Co., Ltd. It featured some additional features, mainly mini-games, a dating game, TV to replace the newspaper, horse races and monster breeding, among others, all of them in 3D. A few new "natural" disasters were also included, most of them being giant monster attacks (players were able to use their monster to fight against them).' FROM games WHERE igdb_id = 365476 ON CONFLICT (game_id, language_code) DO NOTHING;
