INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 2', 'Resident Evil 2 is a sequel to the first Resident Evil title. Like the previous game in the series, Resident Evil 2 is a 3D action-adventure using three-dimensional polygon characters over two-dimensional pre-rendered backgrounds, with the action viewed through a variety of cinematic fixed camera angles in each room. Players can choose to play as one of two possible characters; each goes through the same initial scenario but with differences in the type of weaponry they find and the people they meet along the way.' FROM games WHERE igdb_id = 880 ON CONFLICT (game_id, language_code) DO NOTHING;
