INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yasashii-tamagotchi', 229845, '1998-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xqo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdx5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yasashii Tamagotchi', 'The instruction manual for the Yasashii retells the story of the Tamagotchi Planet getting drunk, forcing the Tamagotchis to flee to Earth. Nearly two years after the incident, it''s time for the Tamagotchis to start returning home. Professor Banzo, who invented the first Tamagotchi toy for them to live in, still wanted to experiment on making a more comfortable environment for the Tamagotchis to live. He and Mikachu eventually create the Yasashii, a larger, more comfortable home for the Tamagotchi to live in with greater ease of providing care. The Yasashii Tamagotchis, also known as "YasaTamagotchis", are Tamagotchis that were born and raised on Earth. Thus, they only know about Tamagotchi Planet based on stories from older Tamagotchis who had lived there. The YasaTamagotchis are excited to return to their home planet for the first time.' FROM games WHERE igdb_id = 229845 ON CONFLICT (game_id, language_code) DO NOTHING;
