INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asteroids--1', 80932, '1998-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co985b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4yv8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteroids', 'Unlike Activision''s earlier remake of an Atari arcade classic, Battlezone, this one stays close to its namesake. Take the original, Atari coin-op game Asteroids, add in the features of the Atari 2600 cartridge, then give it 3-D graphics and a bunch of power-ups, and you''ve got Activision''s Asteroids remake. There are three types of ships to choose from, each with different strengths and weaknesses. There are also three skill levels. If you beat the game at Expert or higher, you gain access to a fourth type of ship. All ships features the standard laser, shield, flip (instantly flips your ship 180 degrees), and hyperspace. There are also limited power-ups you can pick up such as GunSat, Mines, Homing Missiles, Plasma Drill, and Trigger Bombs. The game supports either one or two players. In two player mode, the object is to simply outscore your opponent in a random zone and level. You cannot directly kill your opponent by shooting him, but there are other ways.... Lastly, if you shoot the classic-style asteroid in level 15 of the first zone, you''ll find the option of "Classic Asteroids" now appearing on the main menu.' FROM games WHERE igdb_id = 80932 ON CONFLICT (game_id, language_code) DO NOTHING;
