INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dink Smallwood', 'Dink Smallwood is a humorous role-playing video game. It was first released in 1998 before becoming freeware on October 17, 1999. It was developed by Robinson Technologies, at the time consisting of Seth Robinson, Justin Martin, and Greg Smith. Mitch Brink composed several of the game''s music tracks, while others are MIDI forms of classical music such as Debussy''s Reverie. The game has a small but dedicated fan following that continues to develop add-ons for the game more than a decade after its release.' FROM games WHERE igdb_id = 11345 ON CONFLICT (game_id, language_code) DO NOTHING;
