INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Race', 'A Koei published monster collecting and racing game in the vein of Pokémon. It was released in Japan on March 6th 1998 for the Sony Playstation and Nintendo Gameboy. In the game you play a young boy who wants to be a monster trainer and win the Monster Race World Championship and for that the player has to train his monster so that way he becomes stronger and faster. The player can also catch new monsters that he can find in grass terrains and if he wins the race against them he can add them to his team.' FROM games WHERE igdb_id = 64019 ON CONFLICT (game_id, language_code) DO NOTHING;
