INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Planet Sucks!', 'This Planet Sucks is Greg Troutman''s first game for the Atari 2600 and is based on the Taito arcade game Lunar Rescue. Your goal in This Planet Sucks is to rescue colonists trapped on the planet''s surface, while avoiding the asteroid belt between your mother ship and the colonists. In addition to fighting gravity and avoiding the asteroids, care must also be taken not to squash the poor colonists you''re trying to save! And to make matters worse, the asteroids turn into enemy ships after rescuing a colonist!' FROM games WHERE igdb_id = 71339 ON CONFLICT (game_id, language_code) DO NOTHING;
