INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakusou Dekotora Densetsu: Otoko Ippiki Yume Kaidoi', 'Bakusou Dekotora Densetsu: Otoko Ippiki Yume Kaidoi is a racing video game developed and released by Human Entertainment, released on June 25, 1998 in Japan. This game puts you in the role of a truck driver in Japan, transporting cargo and competing in illegal races against other trucks.' FROM games WHERE igdb_id = 60417 ON CONFLICT (game_id, language_code) DO NOTHING;
