INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganso Family Mahjong', 'Ganso Family Mahjong is a mahjong game is which the player is a gambler (male or female one, since the game allows the player to choose a name, genre, blood type, etc) that in the new story mode he goes through some kind of board in which he advance playing mahjong matches againts computer opponents. The game also features a tournament mode, a free game mode and also a complete tutorial.' FROM games WHERE igdb_id = 377545 ON CONFLICT (game_id, language_code) DO NOTHING;
