INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vigilante 8', 'Vigilante 8 is a vehicular-combat game set in an alternate 1975. Australian terrorist Sid Burn is hired by OMAR to dispose of all competing oil companies in the U.S. so that OMAR can establish an oil monopoly in the country. After hearing reports of destruction by Sid Burn''s gang, the Coyotes, a man named Convoy, a kind-hearted trucker, forms a group of his own, the Vigilantes, to combat the Coyotes and stop the tyranny of OMAR.' FROM games WHERE igdb_id = 3332 ON CONFLICT (game_id, language_code) DO NOTHING;
