INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-stunt-track-driver', 26688, '1998-10-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cla.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8eu2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels Stunt Track Driver', 'The little die-cast cars from Matchbox make their way to the Game Boy Color with HOT WHEELS STUNT TRACK DRIVER. You can choose from five different Hot Wheels cars, including Way 2 Fast, Tow Jam, Shadow Jet, Saltflat Racer and the Twin Mill each with unique strengths and weaknesses. After picking the right car, take it for a test drive on one of the six tracks in the Single Race mode. When you want some stiff competition, try to win successive races in the Tournament mode. And if your friends think they can drive better than you, make them prove it with the two-player link cable option. In all of the modes, the key to winning is to maximize your speed by pulling off big stunts. Find out if you have what it takes to become a Hot Wheels Driver in HOT WHEELS STUNT TRACK DRIVER.' FROM games WHERE igdb_id = 26688 ON CONFLICT (game_id, language_code) DO NOTHING;
