INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('uprising-x', 45030, '1998-12-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co988f.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uprising-X', 'A war has been going on for nearly two hundred years between the cruel Imperium regime and the Rebel forces. The Rebels are beginning to turn the tides of the war to their advantage, and while the Imperium armies are by no means defeated, there is a great deal of hope in the Rebel camp. Unfortunately, the Imperium has introduced a new weapon of unspeakable power. When unleashed against a Rebel planet, the damage was absolute. This new "planet-killing" weapon will certainly mark the end of the Rebel forces if it continues to operate. Uprising X, by The 3DO Company, is a blend of action and strategy for the PlayStation. Players take control of a tank-like vehicle known as "The Wraith," which is the most powerful weapon available to the Rebel forces. The majority of the game is spent behind the controls of the Wraith, although some missions will require troop deployment and the construction of Rebel equipment. The game utilizes a first-person view from inside the Wraith or while building in Citadel mode.' FROM games WHERE igdb_id = 45030 ON CONFLICT (game_id, language_code) DO NOTHING;
