INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kartia-the-word-of-fate', 45222, '1998-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uh9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc81y0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kartia: The Word of Fate', 'Kartia: The Word of Fate (or simply Kartia), known as Legend of Kartia in Europe and Rebus in Japan, is a tactical role-playing game developed and published by Atlus for Sony''s PlayStation video game console in 1998. It is best known for the work of its art designer, Yoshitaka Amano, who had previously worked on the Final Fantasy series. Shigenori Soejima, another artist who would later be known for his work on the Persona series, also contributed to the game as an item graphics artist. The game was re-released on the Japanese PlayStation Network in 2011. Story: After numerous wars, peace was brought to the land by the power of Kartia... Yet, in this peaceful land, evil desires lived within the hearts of the people. This is the story of a boy and girl who courageously lived through this chaotic era...' FROM games WHERE igdb_id = 45222 ON CONFLICT (game_id, language_code) DO NOTHING;
