INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sound Journal for Lovers', 'Sound Journal for Lovers is a Downloadable Soundlink game for the Satellaview that was broadcast in 2 different volumes between February 8, 1998 and February 14, 1998. Sound Journal for Lovers comprises a set of text and images meant to smoothly accompany the music that played during the St.GIGA broadcast hour. The majority of the contents are screens displaying an artist listing and lyrics scrolling upwards. Of the minor interactions available to the player, a toggle option changes the lyrics from English to a Japanese translation. Some songs do not have an associated listing for lyrics.' FROM games WHERE igdb_id = 150215 ON CONFLICT (game_id, language_code) DO NOTHING;
