INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-clancy-s-ruthless-com', 1858, '1998-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yp3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s ruthless.com', 'This isn''t business. This is war. How far will you go? The simultaneous turn-based strategy game that lets you build a corporation atop the bodies of your competition. Use thugs, hackers or the occasional lawyer to get what you want, the way you want. You don''t need ethics, just greed, ego and a few wicked instincts. Ever thrown a lawyer off a pier? Hacked into a mainframe to swipe classified information? If not, then it''s time you went into business with Tom Clancy''s ruthless.com. Find out if you have what it takes not only to survive but to dominate in an industry of cutthroats and corporate raiders. You can forget about ethics- succeeding here means putting all your strategy skills into beefing up your bottom line. But don''t worry. You''ll have help. A vicious gallery of hackers, thugs and lawyers are waiting to carry out your every greedy whim. And if they fail you, fire them. Or fire at them. Just don''t expect this to be some sissy business sim. You and up to five other competitors do whatever it takes to build a software empire. In the end, the only thing anyone will remember is who comes out on top.' FROM games WHERE igdb_id = 1858 ON CONFLICT (game_id, language_code) DO NOTHING;
