INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Varginha Incident', 'An overwhelming military operation is in progress to cover up the landing of an alien spacecraft. Frustrating the military personnel involved, some aliens escape towards the city, where they are spotted by several eyewitnesses. You are one of those witnesses - the first who actually makes contact - and who is assigned a very special mission...' FROM games WHERE igdb_id = 2535 ON CONFLICT (game_id, language_code) DO NOTHING;
