INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fisher-Price Little People Christmas Activity Center', 'Join Dudley the Elf and help him get ready for Christmas with Fisher-Price Little People Christmas Activity Center. There are ten holiday crafts and activities to do including such tasks as decorating the Christmas tree, placing presents around it or heading outside to build and decorate a snowman. Many of the activity results can be printed using Avery Kids printable stickers. Back inside once more, you can choose any number of Christmas craft activities and then join Dudley and the other Little People for a sing along of five perennial favorite Christmas carols such as "Deck the Halls," "Up on the Housetop," and "Jingle Bells."' FROM games WHERE igdb_id = 337173 ON CONFLICT (game_id, language_code) DO NOTHING;
