INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asghan: The Dragon Slayer', 'Asghan: The Dragon Slayer is a fantasy-themed hack-and-slash action role-playing Game. Players take on the persona of Asghan, a warrior prince who swears to avenge the death of his father by dragons. The game is praised for smooth integration of action and role-playing elements as well as a wide array of enemies and weapons. It suffers, however, from lacking character development and awkward controls.' FROM games WHERE igdb_id = 10860 ON CONFLICT (game_id, language_code) DO NOTHING;
