INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O.D.T.: Escape... ...Or Die Trying', 'Find yourself immersed in an atmosphere of mystery, magic and mayhem. Fight your way through incredible, multi-leveled, 3D worlds while searching for a magical green pearl that will help save millions from decimation. With hand-to-hand combat, devastating weapon power and some amazing magic spells, O.D.T. leads you deep into a mysterious tower full of hideous enemies and hidden dangers - it gets tough but there''s no turning back!' FROM games WHERE igdb_id = 45213 ON CONFLICT (game_id, language_code) DO NOTHING;
