INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'E''tude Prologue: Yureugoku Kokoro no Katachi', 'A coastal town called "South Aose" surrounded by the sea and mountains is a place where lots of nature still remains. Two normal high school students go to a school in this town. The story starts in the special winter of the 3rd year of school when these two protagonists meet.' FROM games WHERE igdb_id = 204482 ON CONFLICT (game_id, language_code) DO NOTHING;
