INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Walt Disney World Explorer: Second Edition', 'A point-and-click application about the Walt Disney World Resort in Florida. Users can explore the sights and sounds of the resort through narrated slideshows, see the resort''s growth on the Walt Disney World Timeline, take guided tours on "Tours of the World", and play various "interactivities" such as The Walt Disney World Quiz Challenge and Oceans of the World. The 1998 released Second Edition adds new topics such Disney''s Animal Kingdom, Disney''s Coronado Springs Resort, and Buzz Lightyear''s Space Ranger Spin.' FROM games WHERE igdb_id = 51375 ON CONFLICT (game_id, language_code) DO NOTHING;
