INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noël: La Niege', 'Noël: La Niege is the second game in the Noël series. In the game you have to communicate with the three girls you met and get acquainted with them by talking to them with video phone and create a future for you and them. The game features Japanese voice acting and lots of full motion video sequences.' FROM games WHERE igdb_id = 107619 ON CONFLICT (game_id, language_code) DO NOTHING;
