INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen-Nippon Joshi Pro Wrestling: Joou Densetsu - Yume no Taikousen', 'To reproduce the behavior of wrestlers, the game uses "motion capture technology". In addition to a realistic player movement, each wrestler is fully featured and authentic. Produce a real battle with the voices of the wrestlers who appears in this game with 13 female fighters. Incorporating live action movie to each wrestler, Zen Nihon Joshi Pro Wrestling: Joou Densetsu - Yume no Taikousen has a rich content.' FROM games WHERE igdb_id = 45029 ON CONFLICT (game_id, language_code) DO NOTHING;
