INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest VIII: The Mask of Eternity', 'King''s Quest: Mask of Eternity (also known as King''s Quest VIII: The Mask of Eternity) is an action-adventure video game written and designed by Roberta Williams and released in 1998 by Sierra Studios, is the eighth, and at present remains the final, official computer game in the famous King''s Quest series. It is the first and only game in the series where the main character is neither King Graham nor a member of his family, the first in the series to use a full 3D engine as opposed to the 2D cartoon or pixel style of the earlier games and the first to omit the sequel numbering system on box artwork and title screen, though references to it being the eighth game appear in the file structure and the game was marketed as KQ8 on the official website, interviews, and other places.' FROM games WHERE igdb_id = 7528 ON CONFLICT (game_id, language_code) DO NOTHING;
