INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blaze & Blade: Eternal Quest', 'Blaze & Blade: Eternal Quest, also known as simply Blaze & Blade, is a multiplayer action role-playing game developed by T&E Soft for the PlayStation and Microsoft Windows. It is the first in the series (the other being Blaze & Blade Busters, which uses the same engine), and the only one released outside Japan.' FROM games WHERE igdb_id = 288139 ON CONFLICT (game_id, language_code) DO NOTHING;
