INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Efficus: Kono Omoi wo Kimi ni...', 'Efficus - Kono Omoi wo Kimi ni... is a dating simulation by Genki that is based on a school social standing, such as who you hand around with and when. Its time is based by a monthly calendar and as the months go by you will be able to advance your social standing with different women, including 2 different teachers at your school.' FROM games WHERE igdb_id = 339910 ON CONFLICT (game_id, language_code) DO NOTHING;
