INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The ClueFinders 3rd Grade Adventures: The Mystery of Mathra', 'Join the ClueFinders deep in the rain forest and learn a year full of 3rd grade skills. A scientist has vanished and animals are disappearing. Has an ancient monster returned? Apply math, reading, science, geography, and problem-solving skills to solve the mystery!' FROM games WHERE igdb_id = 72192 ON CONFLICT (game_id, language_code) DO NOTHING;
