INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kattobi Tune', 'Kattobi Tune is a circuit/tune edition unique episode of the Shutoko Battle series (aka Tokyo Xtreme Racers). Kattobi Tune was compiled under the supervision of Rev Speed, a popular Japanese car tuning magazine and features seven licensed professional tuners, RE Amemiya, Spoon, Mine''s, Trial, "RS Yamamoto", Garage Saurus and JUN Auto, appearing years later in Racing Battle: C1 Grand Prix and also in the influential Gran Turismo series by Polyphony Digital. In Kattobi Tune''s career, you follow a text-driven story as you slowly work your way towards faster and faster cars, either by an extensive car tuning' FROM games WHERE igdb_id = 214618 ON CONFLICT (game_id, language_code) DO NOTHING;
