INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-dance-revolution', 3679, '1998-09-26', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2puf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ctk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution', 'Dance Dance Revolution (ダンスダンスレボリューション Dansu Dansu Reboryūshon?), abbreviated DDR and also known as Dancing Stage in earlier games in Europe and Australasia, and some other games in Japan, is a music video game series produced by Konami. Introduced in Japan in 1998 as part of the Bemani series, and released in North America and Europe in 1999, Dance Dance Revolution is the pioneering series of the rhythm and dance genre in video games. Players stand on a "dance platform" or stage and hit colored arrows laid out in a cross with their feet to musical and visual cues. Players are judged by how well they time their dance to the patterns presented to them and are allowed to choose more music to play to if they receive a passing score. Dance Dance Revolution has been given much critical acclaim for its originality and stamina in the video game market. There have been dozens of arcade-based releases across several countries and hundreds of home video game console releases, promoting a music library of original songs produced by Konami''s in-house artists and an eclectic set of licensed music from many different genres. The DDR series has inspired similar games such as Pump It Up by Andamiro and In the Groove by Roxor' FROM games WHERE igdb_id = 3679 ON CONFLICT (game_id, language_code) DO NOTHING;
