INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mawatte Mucho!', 'Action puzzle game where the goal is to move blocks by spinning them. The gameplay is to liberate three pink creatures by open the three blue chests of each level and then go to the goal, the levels are in some stages divide into two sublevels, and you move between them using a blue teleporter, and in round four of each world you must defeat a boss to complete that level.' FROM games WHERE igdb_id = 366045 ON CONFLICT (game_id, language_code) DO NOTHING;
