INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astronoka', 'Astronoka is officially described as a "space vegetable production and pest control game". The game revolves around the player cultivating vegetables on a fictional, futuristic star system. The objective is to win vegetable contests and eventually the All-Universe Vegetable Competition, while setting traps and defense to protect the farm against a species of pest called Baboo.' FROM games WHERE igdb_id = 94714 ON CONFLICT (game_id, language_code) DO NOTHING;
