INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunbare! Game Tengoku: The Game Paradise 2', 'PlayStation-only sequel to Jaleco''s crossover cute-''em-up. The system uses a gun controller connected to the 2P controller socket to provide cover fire for the shooter. The title of the game is therefore a combination of Gun and the Japanese word Ganbare (Don''t give up!). Even if you don''t have a gun controller, you can use a DualShock controller to shoot for cover.' FROM games WHERE igdb_id = 56031 ON CONFLICT (game_id, language_code) DO NOTHING;
