INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parasite Eve', 'Parasite Eve is a survival horror role-playing video game developed and published by SquareSoft (now Square Enix) for the Sony PlayStation console. The game follows the story of Aya Brea, a rookie NYPD officer who becomes embroiled in a series of bizarre and deadly events related to a genetic mutation known as mitochondria. The game combines elements of horror, science fiction, and RPG gameplay, featuring real-time battles, exploration, puzzle-solving, and character development. The game''s plot is inspired by the novel of the same name by Hideaki Sena, and its gameplay mechanics were influenced by the Final Fantasy series. Parasite Eve was critically acclaimed upon its release in 1998, and is widely regarded as a classic of the survival horror genre.' FROM games WHERE igdb_id = 7357 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 7357 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
