INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('air-boarder-64', 47763, '1998-03-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co54up.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yaf6fszvwxuotwuu2sly.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Boarder 64', 'Air Boarder 64 is a futuristic racing game for the Nintendo 64. It is very similar to the Tony Hawks Pro Skater series, although the game features hover boards instead of the usual skateboards. Various game modes are available in which you either have to win the race challenges or get a high score by performing different tricks. The North American version was supposed to release as ''AirBoardin'' USA'' but was canceled.' FROM games WHERE igdb_id = 47763 ON CONFLICT (game_id, language_code) DO NOTHING;
