INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Roman: Power of Dark Side', 'A PS1 RPG with 3-D models and pre-rendered backdrops, Ancient Roman was released in 1998 by Nihon System, but exploded into internet infamy in the late 2010s as word of the game began to spread through Japanese gaming circles. It is now widely considered to be one of the worst RPGs ever made by Japanese retro gamers.' FROM games WHERE igdb_id = 193330 ON CONFLICT (game_id, language_code) DO NOTHING;
