INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Arts', 'Walk into the arena, take a bow, and prepare for the most intense combat simulation ever! Over nine controllable fighters are yours to command, complete with an arsenal of face-busting, body-smashing moves. Feel every kick, punch and throw with the RUMBLE PAK feature as you take part in a low down and dirty street fighting tournament!' FROM games WHERE igdb_id = 10612 ON CONFLICT (game_id, language_code) DO NOTHING;
