INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crash-bandicoot-warped', 1187, '1998-11-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co873w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3so6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot: Warped', 'Crash Bandicoot: Warped is the third game in the Crash Bandicoot series and the first to feature Coco as a playable character. The player takes control of Crash and Coco Bandicoot, who must travel back and forward in time and gather 25 crystals before Uka Uka and Doctor Neo Cortex can do so. Much of the game takes place in the Time Twister which acts as the hub area of the game. The Time-Twister is split up into five chambers, each chamber has five buttons that open portals to different levels. The goal in each level is to find and obtain the crystal hidden in the level. Crash Bandicoot: Warped was lauded by critics in many areas, and the game has been considered one of the best video games of all time.' FROM games WHERE igdb_id = 1187 ON CONFLICT (game_id, language_code) DO NOTHING;
