INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Humpty''s Scramble', 'This game was made to promote the western-Canadian family restaurant chain "Humpty''s" and their Kids'' Club.   In this 1998 DOS platformer, Humpty must rescue his little buddy Hammlet from an evil wizard by traversing various areas including a forest, a marine cave, a mountain, and a maze-like castle.  The game was sold and distributed for free at certain locations. Despite having a rather limited release, it impressively touted pre-rendered 3D visuals and a first-person 3d maze in its final area.' FROM games WHERE igdb_id = 144139 ON CONFLICT (game_id, language_code) DO NOTHING;
