INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tun-town', 68866, '1998-02-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co686p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4x1n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tun Town', 'The story of Tun Town takes place in the small town of the same name. The student LeLe returns to Tun Town during the summer holidays. He discovers that there is a war going on between dogs and cats. Under leadership of the Cat King, the cats have defeated the dogs. LeLe and his friends unite the dogs and beat Cat King to bring back peace to the town. But the gangs in the big cities also want control over the town. Lele, his dog friends, Cat King and the cats form an alliance to fight and defend their hometown. Tun Town is a Chinese-made role-playing game. The gameplay system is similar to that of Japanese-style RPGs, with party management, simple turn-based battles, and automatic leveling up. It is possible to collect parts to build different kinds of weapons in the game. The visuals are cartoon-like, and the plot has humorous elements.' FROM games WHERE igdb_id = 68866 ON CONFLICT (game_id, language_code) DO NOTHING;
