INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Rainbow Six', 'A combination of explosive action and real-life strategy! The most revolutionary action/strategy game of its kind. Nothing comes closer to offering an exciting combination of strategy, team-building, realistic three-dimensional graphics and true-to-life special forces action. The ultimate goal is to save yourself and the world from deadly terrorists. You must successfully complete 17 unique missions. If you die, the game isn''t over. The World is.' FROM games WHERE igdb_id = 1842 ON CONFLICT (game_id, language_code) DO NOTHING;
