INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers III', 'The gods may be crazy! First the Almighty He, the highest of all the gods, sends Jupiter, Horus, and Ch''ih-Yu off into an extremely arduous competition simply on account of some occasional drinking sprees! Then the three gods are subjected to scorn and derision: Q''nqura, the goddess of the Amazons, lets the trio win in battle out of pure spite, and then their humiliation is complete!' FROM games WHERE igdb_id = 3696 ON CONFLICT (game_id, language_code) DO NOTHING;
