INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross Madness', 'Motocross Madness is a extreme sport racing simulation.  The game is known for its realism, including terrain, audio, and "bone-chilling" motorcycle wrecks. If the player is in Stunt mode, goes out of bounds, and gets on a large cliff, an "invisible slingshot" will cause the player and the bike fly across while a funny sound plays until both objects will hit the ground.' FROM games WHERE igdb_id = 10260 ON CONFLICT (game_id, language_code) DO NOTHING;
