INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('seirei-shoukan-princess-of-darkness', 138925, '1998-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co776e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar40rm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seirei Shoukan: Princess of Darkness', 'A tactical RPG with dating sim elements. In this game, players take on the role of the prince from the Clan of Light, Fritz, forming contracts with the five great spirits of ''Light,'' ''Fire,'' ''Water,'' ''Wind,'' and ''Earth.'' Their objective is to rescue the princess of light, who is Fritz sister, and together, defeat the Demon King. The game consists of a total of 13 chapters, each featuring battles. After each battle, there are conversation events that allow players to deepen their relationships with the various spirits, ultimately leading to different endings. A sequel entitled Lunar Wing was released in 2001.' FROM games WHERE igdb_id = 138925 ON CONFLICT (game_id, language_code) DO NOTHING;
