INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('digimon-adventure--1', 247397, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7znl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scma0p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Adventure', 'Digimon Adventure (aka Digimon) is a bootleg platformer for the SNES and Game Boy Advance based on Digimon. Digimon Adventure uses the same engine as Pocket Monster, thus the gameplay mechanics are the same. The game spans six levels, which include two boss fights. The only playable character is Agumon. The player can attack enemies by pressing A to shoot a fireball. Each level has a strawberry item that, once collected, transforms that the player into Greymon, who''s fireball attack is much larger and stronger. Once the player loses all their lives, they''re given a chance to continue, which seems to have no limit. The game steals nearly all of its graphics from numerous other sources. Of all the levels, so far the only identified source is the background from the last battle being taken from Castlevania Dracula X. The sound engine and music are also stolen from Bonkers for the SNES, which, like the game engine, is also used in Pocket Monster and Pokemon Gold and Silver.' FROM games WHERE igdb_id = 247397 ON CONFLICT (game_id, language_code) DO NOTHING;
