INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n Pop', 'Pop''n Pop is a puzzle game similar to Puzzle Bobble; the player''s goal is to release colored bubbles from the bottom on the screen within a limited amount of time, trying to match three or more bubbles of the same color. The difference in this version is that bubbles cannot bounce on the walls; the player can only release them vertically. The game features characters from various Taito games, such as Bub and Bob from the Bubble Bobble series, Tiki from The New Zealand Story, the dwarves from Doko Doko Don, and others.' FROM games WHERE igdb_id = 64307 ON CONFLICT (game_id, language_code) DO NOTHING;
