INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rummel & Rabalder: Jakten på Kapten Hanssons Guld', '"Rummel & Rabalder: The Hunt for Captain Hansson''s Gold" is a Swedish computer game from 1998 produced by Utero Digital Media AB , based on an idea by Lars Anttinen. The game is based on TV4 ''s characters Rummel and Rabalder from the TV series of the same name by Lattjo Lajban , created by Torbjörn Jansson , who also wrote the script for the game.' FROM games WHERE igdb_id = 154827 ON CONFLICT (game_id, language_code) DO NOTHING;
