INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Reading Quest with Aladdin', 'Your child will be whisked away to learning adventures that build essential reading skills and challenge the imagination. Genie, Jasmine, Iago, and the gang are here to cheer kids on with encouragement and helpful hints. Watch them improve their skill levels as they journey to free Aladdin.' FROM games WHERE igdb_id = 208897 ON CONFLICT (game_id, language_code) DO NOTHING;
