INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rush-2-extreme-racing-usa', 3593, '1998-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39y7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc97nx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rush 2: Extreme Racing USA', 'Rush 2: Extreme Racing USA is a sequel to San Francisco Rush and the second game in the Rush series. The game is notable for the high level of detail in the recreations of the various cities and states used, and for its fast arcade-style physics. The game also features a two-player mode and rumble pack support. Hidden shortcuts and jumps add to the replay value of the game. Cities used are New York (Uptown and Downtown), Hawaii, Las Vegas, San Francisco (Alcatraz), Los Angeles, and Seattle. Other tracks playable at the start of the game are Stunt, Crash, and Halfpipe. A bonus track can be won where your car is miniaturized and you drive through the offices of Midway Games. Another bonus is the full pipe level, as the last achievement to unlock.' FROM games WHERE igdb_id = 3593 ON CONFLICT (game_id, language_code) DO NOTHING;
