INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-adventures-in-typing-with-timon-and-pumbaa', 167278, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7x2d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scczfu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Adventures in Typing with Timon & Pumbaa', 'Rafiki, Timon and Pumbaa from Disney''s Lion King are the tutors in this typing game created for children ages 6 and up. The comedic meerkat and warthog team are "going off on an adventure to broaden their horizons", and wise old Rafiki advises them to bring along his keyboard. When they demur, Rafiki enjoins the player to assist them in their travels, and the typing tutorial begins. The game employs standard practice routines, beginning with proper posture and placement of the fingers on the keys, followed by letter repetitions as each section of the keyboard is mastered. At first the exercises focus on accuracy, later working up to increasing the player''s typing speed. Keyboard exercises are interspersed with mini typing games that become available as the player progresses: Milestones are rewarded with printable certificates, and Rafiki keeps a progress report of the player''s WPM (words per minute) and accuracy statistics, as well as showing which keys the player needs to work on. There is a Ctrl + P option at the sign-in page that allows the unlocking of all the games and lessons.' FROM games WHERE igdb_id = 167278 ON CONFLICT (game_id, language_code) DO NOTHING;
