INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goiken Muyou II', 'Goiken Muyou 2 is a 3d fighting game that features 10 characters (male & female ones) and different game modes (story mode, arcade, vs, tag team, etc). Programmed by ex-members of the Virtua Fighter team, this game has a yankee style, biker gang feel to it with characters varying from high school students to a yakuza type gangster via a wrestling-loving English teacher. The title means ''your opinion is worthless''. Fair enough.' FROM games WHERE igdb_id = 43831 ON CONFLICT (game_id, language_code) DO NOTHING;
