INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burnout-championship-drag-racing', 2404, '1998-03-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pdaromcxqqql3j11fuki.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxn3o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burnout: Championship Drag Racing', 'Burnout is a racing simulation devoted to the world of drag racing. You fine-tune your car in the hopes of then being able to send it at insanely high speeds in short, linear tracks. And this is what makes the bulk of the game, a dizzying array of customization options are available for you to construct the perfect hot-rod, essentially making it a "grease monkey" simulation. Additional features include bracket racing (where you select an estimated time based on your practice runs, and try to meet it against other cars), quick race and a complete season against 64 computer controlled cars. Also available is multiplayer racing through modem, LAN or internet. The graphics engine is a suped-up version of the X-Car engine, and supports 3D acceleration with all sorts of nifty effects such as smoke, sparks, tire distortion, etc.' FROM games WHERE igdb_id = 2404 ON CONFLICT (game_id, language_code) DO NOTHING;
