INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shoujo-kakumei-utena-itsuka-kakumei-sareru-monogatari', 46051, '1998-05-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30sx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gsxlxfqqohmnjpewzzee.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shoujo Kakumei Utena: Itsuka Kakumei Sareru Monogatari', 'Based on the 1997 anime, Shoujo Kakumei Utena: Itsuka Kakumei Sareru Monogatari tells an original story which is set between episodes eight and nine of the TV series. The main character of the game is an original character who transfers to Ohtori Academy. The game is in the style of a visual novel with strong dating sim elements. The major characters each possess a statistic called "Heart''s Nobility" which the player affects through dialog choices that appear sporadically during play. Each character''s level of Heart''s Nobility determines how the game will end. The special endings available for characters that end with particularly high Heart''s Nobility represent the game''s dating sim element, but because it is set within the larger plot of the TV series the relationships are usually somewhat platonic, or one-sided affections on the part of the main character.' FROM games WHERE igdb_id = 46051 ON CONFLICT (game_id, language_code) DO NOTHING;
