INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mech Frontier: Kinkyuu Shirei! Wakusei Shigen wo Kakuho se yo', 'A real-time strategy game "Mech Frontier-Urgent Command! Secure Planetary Resources-" features a fierce battle for resource acquisition with hostile forces taking place on a planet in the near future. As a development commander, the player builds plants for various purposes such as mining and processing resources, supplying energy, and maintaining and repairing robots on the planet, and carrying out the task of sending mined resources to the earth. Can you accomplish this mission by overcoming the many obstacles that stand in your way?' FROM games WHERE igdb_id = 141734 ON CONFLICT (game_id, language_code) DO NOTHING;
