INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elder Scrolls Adventures: Redguard', 'You play as Cyrus, a Redguard in search for his sister, and a mercenary pirate. After receiving a letter from your old friend and Nord captain Tobias about your sister''s disappearance, you sail to Stros M''kai, your sister''s home, and site of the final clash between the Redguard Crowns and the Empire. The game begins when you arrive at the port.' FROM games WHERE igdb_id = 55 ON CONFLICT (game_id, language_code) DO NOTHING;
