INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Warrior Monsters', 'Dragon Quest Monsters is a turn-based RPG that involves recruiting monsters to fight for you in random encounters. Two recruited monsters can be fused together for a better one and extra monsters can be stored on a farm while not in your party. It was released in Japan for the Game Boy Color before the system was released.' FROM games WHERE igdb_id = 24818 ON CONFLICT (game_id, language_code) DO NOTHING;
