INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shogo: Mobile Armor Division', 'Control ultra-powerful mecha that run, jump, duck, strafe, swim, and stomp on enemy personnel. Wield gigantic, super-destructive weapons, and transform into a hover tank in 800 milliseconds flat. You may have driven giant robots, but you''ve never piloted Mobile Combat Armor... until now.' FROM games WHERE igdb_id = 12464 ON CONFLICT (game_id, language_code) DO NOTHING;
