INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kid-pilot--1', 375866, '1998-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coas7z.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Pilot', 'Kid Pilot is an educational flight simulator designed for elementary school children. It allows aspiring aviators to take to the skies across America. With help from friendly penguin Penwick, players can choose a scenario (midflight, take-off, or landing), difficulty level, time of day, location, and one of three planes to command. From big cities like New York and San Francisco to natural wonders like Crater Lake and the Grand Canyon, there are different places to explore, each accompanied by factoids and historical notes announced by Penwick in the air. Kid-friendly controls support joystick or keyboard play, with on-screen instruments like a compass and attitude indicator to assist navigation. Players can practice aerial maneuvers, weave through skyscrapers and mountain passes, and snap pictures for their scrap book, all while learning the basics of flight and the facts behind America''s most famous places.' FROM games WHERE igdb_id = 375866 ON CONFLICT (game_id, language_code) DO NOTHING;
