INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider III: Adventures of Lara Croft', 'Tomb Raider III: Adventures of Lara Croft is a platform and third-person shooter game developed by Core Design and published by Eidos Interactive. It is the third installment in the Tomb Raider series and the sequel to Tomb Raider II. The gameplay system is similar to the one implemented in the previous game. Lara''s abilities include running, jumping, climbing, swimming, rolling, crouching, crawling, sprinting, and swinging on bars and vines. A few new types of hazards have been added in this installment, including cold water in which Lara can swim for a limited amount of time, dangerous underwater creatures (such as piranhas), and the treacherous quicksand, which will swallow the heroine if the player isn''t careful and fast enough to prevent her from falling into it.' FROM games WHERE igdb_id = 1157 ON CONFLICT (game_id, language_code) DO NOTHING;
