INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Fox In: Cheese Chase', 'That pretty blue kitty has heisted the famous fromage and it''s up to kids to catch her! SPY scooters, jet-skis and ultralights are just a few of the racey rides kids need to outrun Blue''s goon squad. Kids also put their creativity to the test as they construct challenging new levels using Professor Quack''s Custom Level Builder.' FROM games WHERE igdb_id = 10839 ON CONFLICT (game_id, language_code) DO NOTHING;
