INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominion: Storm Over Gift 3', 'Dominion: Storm Over Gift 3 is a military science fiction real-time strategy video game developed by Ion Storm and published by Eidos Interactive and released for Microsoft Windows on June 11, 1998. The game was originally developed as a spin-off of the mech simulation game G-Nome by 7th Level.' FROM games WHERE igdb_id = 68207 ON CONFLICT (game_id, language_code) DO NOTHING;
