INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('running-wild', 44973, '1998-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qub.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwp30.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Running Wild', 'A racing game in the purest sense of the word, Running Wild pits six bipedal animals against one another in a footrace across six diverse environments (two of which must be unlocked), with the sole aim of being crowned the fastest animal on the planet. The menagerie of racers includes Mei-Ling the panda, Gwynn the rabbit, Brazz the zebra, General the mountain ram, Coronado the bull, and Boris the elephant. The courses, taking place in remote locations such as the arctic, jungle, and desert, are littered with hazards and power-ups to both aid and hinder your progress. The former is made up of a plethora of obstacles such as pipes, ice and lava pits, thorn patches, and other such impediments, many of which must be cleared using your animal''s innate jumping ability. The power-ups provided allow characters to fly; turn into ghosts in order to avoid obstructions; transform the course into mud or ice or even increase in size in order to squash any competitors in their path. Speed strips are scattered about the locales and will provide much-needed boosts when run over.' FROM games WHERE igdb_id = 44973 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 44973 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
