INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters: Kyo', 'The King of Fighters: Kyo is a visual novel on the The King of Fighters series developed by Yumekobo and released by SNK on the PlayStation on August 27, 1998. The art for this game was produced by the same illustrator of the manga, Masato Natsumoto. It was re-released on PSN as a PSOne Classics on June 28, 2007. An unofficial Spanish translation was released in 2013.' FROM games WHERE igdb_id = 43841 ON CONFLICT (game_id, language_code) DO NOTHING;
