INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skullmonkeys', 10917, '1998-01-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1o53.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6w3g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skullmonkeys', 'Something has gone seriously wrong in Klayman''s homeland -- Klogg, an evil megalomaniac, wants to destroy the land and basically rule over anything and everyone. Because the task can get difficult at times, he has enlisted the service of fearsome ape-like creatures, Skullmonkeys, to aid in the destruction of planet Idznak. Needless to say, it is up to the player to stop Klogg and his devious plans. Much like The Neverhood, Skullmonkeys is a 2D platformer built entirely of Claymation characters, enemies, and environments. Throughout the game''s seven worlds spanning ninety levels, the basic objective of each is to destroy as many Skullmonkeys as possible. Destroying the simians can be done one of two ways: firing projectile weapons or butt-bouncing off their heads.' FROM games WHERE igdb_id = 10917 ON CONFLICT (game_id, language_code) DO NOTHING;
