INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thunder-brigade', 22843, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55nx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8nv3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Brigade', 'Thunder Brigade is a PC game released in 1998. It is an action/arcade tank sim game which involves piloting floating tanks in a sci-fi universe shooting down enemy tanks and destroying enemy installations. The war is fought between 3 contrasting factions on numerous worlds. Developed and published by Interactive Magic and Bluemoon interactive, Thunder Brigade features a 30-mission campaign mode, dozens of single scenarios as well as a scenario editor with almost limitless posiblities. Originaly, the game featured an online multiplayer mode which was similar to single scenario and featured an editor. Unfortunatly, the main connection type, "play on imagic.com" has now closed down so multiplayer no longer works properly. Thunder Brigade however is still popular today thanks to it''s addictive gameplay, imaginative universe and the almost infinite possibilities of the scenario editor.' FROM games WHERE igdb_id = 22843 ON CONFLICT (game_id, language_code) DO NOTHING;
