INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('black-dahlia', 12405, '1998-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25j9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ejtprrcl8sxdasfxqiyf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Dahlia', 'Black Dahlia is a suspense thriller based loosely on the unsolved California murder of Elizabeth Short, nicknamed "Black Dahlia" for her favoritism towards black clothing.  The game is a point-and-click puzzle-solving adventure with live action cutscenes. Full 360 degree horizontal and limited vertical panning allow the player to scan each scene with the mouse. Jim''s in-game notebook acts as a journal as it records everything of importance that he has examined. Black Dahlia has over sixty puzzles dispersed over nearly as many locations. They range in difficulty, style and type including jigsaw, manipulation, code breaking, mazes and object based. Well publicized bypass codes can be used to "auto-solve" them without compromising the game, since no score is kept.' FROM games WHERE igdb_id = 12405 ON CONFLICT (game_id, language_code) DO NOTHING;
