INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dogz-3-your-virtual-petz', 151540, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31wh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scae5b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dogz 3: Your Virtual Petz', 'In Dogz 3, you can select a dog, name it, adopt it, and then take it home to your desktop and watch it grow day by day. In this version, several new breeds have been added. You can also dress your mutts in a variety of clothing including hats, sweaters, and pants. This version also supports several different backgrounds including a kitchen, a backyard, a living room, and more. Take your pet to the different rooms and watch the fun. All of the rooms have some new features also, and you can light the fire in the living room and put items in the kitchen refrigerator. Designed to entertain the whole family, Dogz 3 can be run as a screensaver or behind your windows so your dogs can grow to adults faster than in previous versions. By purchasing Catz3, you can watch your dog and cat grow up and play together.' FROM games WHERE igdb_id = 151540 ON CONFLICT (game_id, language_code) DO NOTHING;
