INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkstalkers 3', 'Darkstalkers 3 is the second sequel in the Darkstalkers series of fighting games by Capcom, originally released for the arcades in 1997. The game was originally planned to be released as Darkstalkers: Jedah''s Damnation in the United States, but this title was only used in the arcade version. New characters added in this version are Donovan, Huitzil (Phobos in Japan), and Pyron, with hidden characters of Dark Talbain and Oboro Bishamon .' FROM games WHERE igdb_id = 4135 ON CONFLICT (game_id, language_code) DO NOTHING;
