INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('101-easy-peasy-things-to-do-with-your-computer', 379610, '1998-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coawz1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '101 Easy-Peasy Things to Do With Your Computer', 'This full-colour activity book and CD-ROM package has been designed for children aged four and over. Onscreen activities include a cyberpet to design and play with, a movie-maker to create simple animations, and themed treasure hunts to create. Key Features include free clip art and clip sounds and print-and-play activities which include finger puppets, dressing up, mobiles and party kids, and links to suitable Internet sites.' FROM games WHERE igdb_id = 379610 ON CONFLICT (game_id, language_code) DO NOTHING;
