INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thunder-force-v-perfect-system', 43913, '1998-05-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7rge.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4nfc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Force V: Perfect System', 'In a grim future where a once-benevolent alien technology has turned against humanity, only a ragtag group of ace pilots can save the Earth from total annihilation. Code name: Thunder Force! Witness the first 32-bit installment of the massively popular shooter series! Five spectacular weapons with multiple power-up levels let you blast through waves of metallic predators, and look good doing it. A constant barrage of innovative enemies keeps you intrigued while you struggle to stay alive. A speaker-imploding soundtrack has your foot tapping as your fingers are mashing. Unbelievable rendered cutscenes draw, no-DRAG you kicking and screaming into the action. Put simply, it''s the ultimate hardcore gaming blast-o-rama!' FROM games WHERE igdb_id = 43913 ON CONFLICT (game_id, language_code) DO NOTHING;
