INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun: Hornet''s Nest', 'Top Gun: Hornet''s Next is the sequel to Top Gun: Fire at Will. Once more you take on the role of US Navy pilot Maverick in his F-18 Hornet. The game features a multi-player mode, instant action and a campaign with 30 missions. In the campaign missions are briefed with full motion videos. Battles in this flight simulator are fought in Columbia, Siberia and the Persian Gulf.' FROM games WHERE igdb_id = 22912 ON CONFLICT (game_id, language_code) DO NOTHING;
