INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baroque', 'Baroque is horror-themed action game with elements of survival gameplay. The whole game is set in the tower: you slowly work your way to the top, fighting demons as you progress. You have HP as well as stamina gauge. If your stamina is depleted, you walk slower and can''t react well in a battle.' FROM games WHERE igdb_id = 147807 ON CONFLICT (game_id, language_code) DO NOTHING;
