INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarBirds', 'It''s the First World War and the conquest of the sky is your mission. Battle your way to that target with WarBirds, the totally three-dimensional, fly by the seat of your pants, dog fight game. Pick from any of six missions from Milk Run to The Swarm to dog fight one-on-one or fill the sky with war planes. Fight against a computer-controlled squadron or link with up to four Lynx friends to determine who is the Greatest World War I Flying Ace.' FROM games WHERE igdb_id = 930 ON CONFLICT (game_id, language_code) DO NOTHING;
