INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Create a Pop Sensation', 'Released in other territories as "Smash Hits: Wannabe a Popstar", Create a Pop Sensation gives players the chance to create their own pop songs from numerous music samples. Hold auditions for band members, strike a recording deal and put on a concert for your adoring fans. If you''re lucky, you''ll make it into the top 20 charts.' FROM games WHERE igdb_id = 369695 ON CONFLICT (game_id, language_code) DO NOTHING;
