INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Daisenryaku 98: Storm Over Europe', '"Advanced Daisenryaku 98" is a strategy simulation game set in World War II. Basically, it follows the orthodox simulation game system of hex system and turn base. The system follows the consumer version, but the rules and thinking routines have all been redesigned, and the number of weapons, specs, parameters, and placement have all been refined to make it even more advanced.' FROM games WHERE igdb_id = 60806 ON CONFLICT (game_id, language_code) DO NOTHING;
