INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pajama Sam''s Lost & Found', 'Climb aboard and join Pajama Sam as he jumps and glides through wild worlds, collecting toys, and dodging dangers along the way! Junior Arcade games are jam packed with fast-and-furious game-play that satisfies kids'' hunger for action and surprises! Starring lovable characters and the high-quality, hand-drawn animation that families have come to expect from Humongous Entertainment, this series will provide hours of action and fun for your children.' FROM games WHERE igdb_id = 10651 ON CONFLICT (game_id, language_code) DO NOTHING;
