INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motteke Tamago with Ganbare Kamonohashi', 'Motteke Tamago with Ganbare! Kamonohashi is a top-down Bomberman-style multiplayer arcade action game, and an enhanced port of the PC Engine game Motteke Tamago. This version includes the same arcade mode as the original release, and also adds a single-player story mode with multiple stages and new creatures to play as other than ducks, such as frogs and platypus.' FROM games WHERE igdb_id = 247571 ON CONFLICT (game_id, language_code) DO NOTHING;
