INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('industry-giant', 9910, '1998-04-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4gvd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argkt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Industry Giant', 'Management game that put the player in charge of controlling an industrial group, with the objective of becoming the best industry giant between various competitors. Experience the soaring heights and the shattering depths of being an industrial giant! A factory, a store and some lorries – a simple beginning can be the start of an illustrious career! Build all types of factories, buy your raw materials at a bargain and manufacture the products that will bring you fame and fortune. All you need now is the right advertising strategy – and watch the tills in your newly opened stores fill up. See what you can do in the toy and sports goods industry. Earn your money from jewelry and furniture. And be prepared for the challenges of the computer age. The automobile and electronics industries will make demands on your organizational skills. What is the competition up to? Are they starting to become a nuisance? Then by them out! If you have enough money, that’s it. Or make your companies running more successful than others! So no one will be able to stop you on your path to success… Industry Giant stands for simple and comfortable commands combined with a high degree of complexity – yet easy to understand.' FROM games WHERE igdb_id = 9910 ON CONFLICT (game_id, language_code) DO NOTHING;
