INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel vs. Capcom: Clash of Super Heroes', 'Marvel vs. Capcom: Clash of Super Heroes is the fifth Marvel Comics-licensed fighting game by Capcom and the third game in the Marvel vs. Capcom series. In contrast to X-Men vs. Street Fighter and Marvel Super Heroes vs. Street Fighter, the game features characters from numerous Capcom franchises such as Mega Man and Strider, rather than just Street Fighter characters. The game takes place within the Marvel comic continuity, as Professor Charles Xavier calls out for heroes to stop him before he merges with the consciousness of Magneto and becomes the being known as Onslaught, the final boss.' FROM games WHERE igdb_id = 8246 ON CONFLICT (game_id, language_code) DO NOTHING;
