INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Tetris Challenge', 'Join Disney''s Mickey, Minnie, Donald and Goofy as they embark on a non-stop adventure full of challenging fun and excitement in Magical Tetris Challenge. Completely addictive, deceptively simple, you''ll go wild in a kaleidoscopic shower of falling Tetris pieces in this magical version of the world''s most popular video game.' FROM games WHERE igdb_id = 3398 ON CONFLICT (game_id, language_code) DO NOTHING;
