INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Spelling', 'JumpStart Spelling is game released by Knowledge Adventure in 1998. It focuses on teaching spelling skills for ages 5-8. It is a part of the JumpStart Learning Games series. In this game, CJ must venture through a prehistoric land to save Edison from some cavemen who have captured him to use him as a light source.' FROM games WHERE igdb_id = 73975 ON CONFLICT (game_id, language_code) DO NOTHING;
