INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Blade 2', 'The Last Blade 2 is a 2D fighting game which features anime-style characters that fight each other with swords, clubs, and even fishing poles. These characters pull off their special moves with that ''quarter-circle-to-half-circle'' and ''double-half-circle'' controller motions, reminiscent of Street Fighter.' FROM games WHERE igdb_id = 76045 ON CONFLICT (game_id, language_code) DO NOTHING;
