INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de Go! 2', 'Densha de Go! 2 Kousoku-hen is a train driving simulation game. It was released in the arcades in Japan in 1998. It was ported to PlayStation, Nintendo 64, WonderSwan, Neo Geo Pocket Color, Windows, Dreamcast, and Game Boy Color. The Nintendo 64 version was titled Densha de Go! 64.' FROM games WHERE igdb_id = 37286 ON CONFLICT (game_id, language_code) DO NOTHING;
