INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme-G: XG2', 'Extreme-G is a futuristic racing game with an emphasis on speed. It also features many weapons and an F-Zero style energy shield and regeneration. You are able to break the sound barrier where you hear a sonic boom and all game audio drops out.' FROM games WHERE igdb_id = 3486 ON CONFLICT (game_id, language_code) DO NOTHING;
