INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gakkou wo Tsukurou!! 2', 'The Gakkou o Tsukurou series places the player in the principal of a school, placing him in charge of management and renovating the school grounds. The player decides everything: The place and the new buildings, the professors, the new places of the school, etc. In this sequel the game features new features like select the uniforms, new class, a lot new school boys and girls, and even enter inside the classroom to select the professor and tell him to teach the boys and girls and improve their stats.' FROM games WHERE igdb_id = 363956 ON CONFLICT (game_id, language_code) DO NOTHING;
