INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-party-edition', 18786, '1998-12-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa5m3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vim.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman: Party Edition', 'Bomberman Party Edition, known in Japan and Europe as Bomberman, is a PlayStation version of the 1983 game Bomberman. In addition to vintage graphics for single player mode, an option for enhanced graphics is added. Battle mode is added to this release, which features 8 courses with 3 levels per course. The single player mode is very similar to the 1983 release of Bomberman. The player controls the titular Bomberman in a wide area, full of destructible and non-destructible blocks. The blocks can be destroyed with bombs, and may contain a power up that increases Bomberman''s walking speed, the size of Bomb explosions, the number of bombs able to be placed, or the ability to explode your bombs with the push of a button or to walk through walls or bombs. Some power ups are temporary, allowing Bomberman to be immune to bombs or monsters. The point of each level is to destroy each monster, and then locate the door, which is located underneath a random block. After every few levels, the player can play a bonus level. The player is invincible, and an endless stream of monsters is to be destroyed by the player. The point is to try to build up score until a bonus life is awarded. Similar in design to Super Bomberman, there are a number of level themes in the single player mode.' FROM games WHERE igdb_id = 18786 ON CONFLICT (game_id, language_code) DO NOTHING;
