INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polda', 'Polda is a point and click adventure game developed by SleepTeam. The main character is a policeman Pankrác whose IQ is not very high but despite this fact he always manages to solve his cases. Somehow... However, he does not always use traditional investigation methods. The game provides the players with challenging puzzles and crazy humor.' FROM games WHERE igdb_id = 9713 ON CONFLICT (game_id, language_code) DO NOTHING;
