INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer Jikkyou Winning Eleven 3: World Cup France ''98', 'World Soccer Jikkyou Winning Eleven 3 World Cup France ''98, is a soccer game published by Konami Sports. This game itself, looks like more an enhanced version of Konami''s recent games Goal Storm and a world series revised of J-League WE3. You''re able to select your favourite team among the 32-qualified team in the World Cup 1998, and even some other 8 good teams. Play in the real World Cup, selfmade tournament, international league, or just in a friendship exhibition. The game features audio comments in six lenguages : English ,French, German , Italian , Spanish and Japanese.' FROM games WHERE igdb_id = 181573 ON CONFLICT (game_id, language_code) DO NOTHING;
