INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild 9', 'Wild 9 is a 2D platformer with 3D graphics, featuring gameplay similar in vein to the company''s Earthworm Jim games. Unique to the game is the The Rig, a weapon the protagonist wields. The Rig functions like an electronic lasso, capable of moving objects as well as carry around and smash enemies, which is often needed to solve puzzles and progress through the game''s ten levels. A few stages focus on avoiding obstacles and taking on boss enemies.' FROM games WHERE igdb_id = 15840 ON CONFLICT (game_id, language_code) DO NOTHING;
