INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morita Shogi 64', 'Morita Shogi 64 is a Japanese virtual board game for the Nintendo 64. It was released only in Japan in 1998. It is the sequel to Saikyō Habu Shōgi, a launch game for the Nintendo 64. The cartridge has a built-in RJ-42 Modem Connection port with which players were able to connect to (now defunct) servers to play against other players all around Japan.' FROM games WHERE igdb_id = 3543 ON CONFLICT (game_id, language_code) DO NOTHING;
