INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PoPoRoGue', 'Poporogue is the sequel to SCEI''s 1996 hit in Japan Popolocrois (also called Popolocrois monogatari). The battles in this game are not random, you can see the monsters on the screen and avoid them. What''s more is that if you choose to escape from a battle, the monsters you ran from will chase you around the dungeon.' FROM games WHERE igdb_id = 79937 ON CONFLICT (game_id, language_code) DO NOTHING;
