INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('commandos-behind-enemy-lines', 879, '1998-07-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar13.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arilg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commandos: Behind Enemy Lines', 'Engage in the ultimate battle of wits and wills with the most ruthless military force in history. Set in the backdrop of WWII, Commandos is a real-time tactical wargame that puts you in command of a squad of elite Allied Commandos whose job is to complete 24 dangerous missions behind enemy lines. Your goal is to thwart the German war effort by means of sabotage and tactical genius.This action-packed strategy war game is set apart by its revolutionary AI, and the ability to control 6 individual commandos, each with a specific skill, as they infiltrate hostile territories and engage in intense combat. Your perilous missions will take you from the parched desert of North Africa to banks of the Rhine, the mountainous fjords of Norway, and the beaches of Normandy.Experience the most realistic, visually stunning graphics with accurate 3D models of more than 350 structures, vehicles, and weapons from the WWII era.' FROM games WHERE igdb_id = 879 ON CONFLICT (game_id, language_code) DO NOTHING;
