INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Den Yttersta Gåtan', 'Adolescence is a difficult time: parents don''t understand and classmates bully. The main character of Den Yttersta Gåtan sits on the window sill and looks sadly out the window with the rain pouring down. Just as she is about to run away, a mysterious messenger from Asgard itself appears, and outside the window a Bivröst appears on which Heimdall is trumpeting Gjallarhorn and announcing the beginning of Ragnarök.' FROM games WHERE igdb_id = 201657 ON CONFLICT (game_id, language_code) DO NOTHING;
