INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GT 64: Championship Edition', 'GT 64: Championship Edition "Grand Tour 64" is a racing video game for the Nintendo 64. Hence its title, it was an official licensed game to All-Japan GT Championship, featuring cars and drivers of the 1997 season. GT and Grand Tour our references to long distance traveling such as in the traditional version of the Grand Tour. It was first released on Super Famicom as Zen-Nippon GT Senshuken. It was also the final game ever published by Ocean Software.' FROM games WHERE igdb_id = 3375 ON CONFLICT (game_id, language_code) DO NOTHING;
