INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Momotaro Dentetsu Jr.: Zenkoku Ramen Meguri no Maki', 'Momotaro Dentetsu jr.: Zenkoku Ramen Meguri no Maki (lit. "Momotaro Electric Railway jr: Rolls around Ramen in Japan") is a video game in the Momotaro Dentetsu series of board game-style video games genre released in 1998, developed by Make and published by Hudson Soft for Game Boy. The game was only released in Japan.' FROM games WHERE igdb_id = 64414 ON CONFLICT (game_id, language_code) DO NOTHING;
