INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('manga-oku-no-hosomichi', 299635, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co858h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs3mm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manga Oku no Hosomichi', 'The game begins in a small 6 tatami wooden apartment. You have no work every day and spend your days going back and forth between your futon and desk, but try to do part-time jobs and training. Your knowledge points will increase and your drawing ability will improve. You can always draw your manuscript. When it is finished, ask the publisher to take a look at it. It may be rejected at first, but you may come up with a good idea while taking a walk to avoid distraction. If your manuscript is accepted and your reading cartoon gains popularity, you can get a serialization. However, serialization is grueling for a weekly manga artist who spits blood. If you do your job admirably despite being pressed by deadlines, you may become a popular manga that is even made into an animated cartoon or movie. Once the comics are released, you can hire assistants and concentrate on the manga you want to draw.' FROM games WHERE igdb_id = 299635 ON CONFLICT (game_id, language_code) DO NOTHING;
