INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meltylancer Re-inforce', 'This Sega Saturn version of MeltyLancer: Re-inforce was released five months after the original PlayStation version of the game, and includes numerous changes and additions: - Battles have been redesigned in a turn-based tactical format rather than the semi-real-time format of the original. - New events have been added to the game, including several which make use of the Saturn''s real time clock. - Several mini-games have been changed or replaced.' FROM games WHERE igdb_id = 340415 ON CONFLICT (game_id, language_code) DO NOTHING;
