INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black/Matrix', 'The original Black/Matrix title was released August 27, 1998 for the Sega Saturn console in Japan. There were two remake releases that add more detailed graphics and additional content: Black/Matrix AD (Advanced) for Sega Dreamcast was released in 1999 and Black/Matrix Cross for Sony Playstation was released in 2000.' FROM games WHERE igdb_id = 45415 ON CONFLICT (game_id, language_code) DO NOTHING;
