INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Duel Monsters', 'Yu-Gi-Oh! Duel Monsters is the second Yu-Gi-Oh! video game, following Yu-Gi-Oh! Monster Capsule: Breed and Battle. It is the first game in the Duel Monsters series and the only game released for the Game Boy. It was published in Japan by Konami on December 16, 1998.' FROM games WHERE igdb_id = 57150 ON CONFLICT (game_id, language_code) DO NOTHING;
