INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goemon''s Great Adventure', 'Goemon and all his friends are back in his greatest adventure yet! Goemon''s Great Adventure combines classic Goemon platform action with an all-new twist. The evil time-traveling nun, Bismaru, has summoned Dochuki, a demon prince, to take over the Earth. But first, she wants to marry him! Can Goemon and his gang stop the demon? Can Dochuki escape the cloying clutches of the wacked-out nun? Will Ebisu ever beat his own dumpling eating record? It''s an adventure you''ll never forget!' FROM games WHERE igdb_id = 3508 ON CONFLICT (game_id, language_code) DO NOTHING;
