INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedy Eggbert', 'Speedy Eggbert is a parallax side-scrolling action game where Eggbert needs to traverse each level using his abilities and power-ups to get to the end of the level. Along the way the player can pick up treasure chests and eggs which acts as extra lives. The game also features networked gameplay where up to 4 players can participate in a game.' FROM games WHERE igdb_id = 18729 ON CONFLICT (game_id, language_code) DO NOTHING;
