INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angelique Duet', 'Angelique Duet is a spin-off of the first Angelique game and one of the titles made to celebrate Koei''s twentieth year anniversary. According to Ruby Party commentary, this title answered popular fan demand for an option to play as the first protagonist''s rival, Rosalia. The Premimum Box edition (PlayStation and Sega Saturn only) includes a special musicbox, bookmarks of the Sacred Guardians, and another colored comic book.' FROM games WHERE igdb_id = 45437 ON CONFLICT (game_id, language_code) DO NOTHING;
