INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jimmy-whites-2-cueball', 45852, '1998-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rhz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm79u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jimmy White''s 2: Cueball', 'Licensed by snooker player Jimmy White, this game is a simulation of not only the British game of snooker, but also of the three main variations of pool. The game is viewed in detailed 3D, allowing you to rotate the table at all angles, either from overhead or using the cue position as a base. Taking a shot involves setting the exact pace and spin of it, and considering what each contact will do to the position of the cue ball, and any balls you may wish to pot afterwards. In the snooker mode playing accurate ''safety'' shots (to prevent your opponent scoring) becomes important as well). In each mode there are 10 computer opponents, and matches can consist of up to 9 frames. A trick-shot editor is also included, allowing you to practice shots and set up challenges. Replays and an undo mode are also included.' FROM games WHERE igdb_id = 45852 ON CONFLICT (game_id, language_code) DO NOTHING;
