INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turok 2: Seeds of Evil', 'Having defeated the Campaigner, Turok throws the Chronocepter into a waiting volcano to destroy it. Unfortunately the blast awakens an even deadlier force - The Primagen. Once again a Turok is tasked with restoring peace to the land and stopping the Primagen from merging Earth with the nether world.' FROM games WHERE igdb_id = 1326 ON CONFLICT (game_id, language_code) DO NOTHING;
