INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madojeongi: Secret of Elysium', 'Madou Monogatari: Secret of Elysium is a first-person dungeon-crawler with minimal to no numerical statuses. The player navigates the maze-like floors of the towers by solving puzzles and defeating enemies. Madou Monogatari: Secret of Elysium was only released in Korea.' FROM games WHERE igdb_id = 252163 ON CONFLICT (game_id, language_code) DO NOTHING;
