INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-unholy-war', 44915, '1998-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nmr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Unholy War', 'The Unholy War is 3D strategy game which uses many different weapons and special attacks. In a head to head two player game, players can strategically position their forces, and then fight the opposition in 3D arcade-style combat. Or, you can take advantage of the tournament mode to play against a whole host of friends (or enemies) in a variety of different combat arenas which all require different strategies.  With 14 different characters, and a variety of skills/weapons including seeker bombs, spawning, teleporting,lasers and other special attacks, The Unholy War uses both air and ground to make a realistic enjoyable gaming experience.' FROM games WHERE igdb_id = 44915 ON CONFLICT (game_id, language_code) DO NOTHING;
