INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wrath-of-darkness', 146635, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2z6t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9fck.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrath of Darkness', 'Your apprenticeship finally is over. You are now officially a sorceress. As you walk along the underground passages that lead to your home village, you reflect with pride upon your accomplishment. Suddenly you stop. Something is wrong, your sixth sense tells you. You hold still, listening for any sign of danger. You hear nothing. Then it strikes you: that is exactly what''s wrong. This close to the village, the air should be filled with the sounds of life. Instead, there is only a horrible silence. Quickly you run for the entrance to the village. You step through the final tunnel. Before you lie the empty streets of your home village. Has it been abandoned? Why? Or did something worse happen? Surely there must be some clue somewhere. You stifle the impulse to run away and set out to explore the village. Wrath of Darkness is an action role-playing game played in first point perspective. It is the story of one dark elven sorceress'' quest for revenge. Wrath of Darkness is no longer distributed as a standalone game. To play Wrath of Darkness, you need to download Lightslayer instead.' FROM games WHERE igdb_id = 146635 ON CONFLICT (game_id, language_code) DO NOTHING;
