INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-world', 27255, '1998-01-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co85g1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ck9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman World', 'Bomber worlds. To complete the areas, you must control Bomberman and set bombs to destroy enemies and obstacles that will lead to the exit. To be able to complete each level, the player must locate and pick up all of the Crystals on the map. Once this is complete, the door to the exit will open, and the player is allowed to move on to the next area. In the fourth area of each world, the player will have to defeat a Dark Force Bomber, and an extra boss that is themed after the type of world the setting is in. Once you defeat a Dark Force Bomber, the player is given a unique battle armor to wear for the next boss battle, which has a normal attack and a special attack. The battle armor is only used for the boss battles, meaning once the player advances to the next world, the battle armor will be lost. As such, it is recommended that players take full advantage of the armor.' FROM games WHERE igdb_id = 27255 ON CONFLICT (game_id, language_code) DO NOTHING;
