INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-Zero X', 'It''s you against 29 other machines competing for the title of F-Zero X Champion. You''re racing at speeds of over 1,000 km/h high above the atmosphere. Your competition comes from every corner of the galaxy and won''t shed a tear at the thought of smashing you off the track. With four-player simultaneous gameplay and the Rumble Pak accessory, you have the fastest racing game on the N64 system!' FROM games WHERE igdb_id = 3489 ON CONFLICT (game_id, language_code) DO NOTHING;
