INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cracking the Conspiracy', 'Cracking the Conspiracy is a point-and-click adventure game released by Pixel Shop Inc. in 1998. The game focuses on science fiction and political secrets. A possible Macintosh version was planned, but never came to development due to lack of demand and Mac hardware.' FROM games WHERE igdb_id = 71817 ON CONFLICT (game_id, language_code) DO NOTHING;
