INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('south-park', 1257, '1998-12-12', 41, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6vcj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6h2q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'South Park', 'Single player takes the form of a "Story" mode divided into five episodes and fifteen linear levels. The player will face weak minions (which change based on the episode), plus occasional sub-bosses which will try to escape into town. The final level is devoted to a unique boss fight. Players use quirky weapons ranging from infinite yellow snowballs to cow launchers and toxic Terrance and Phillip dolls. Every weapon has a secondary fire, and players switch between the four main characters when they switch weapons - each of the four kids shares a single life bar because of this. The kids will comment on game actions as they occur, with heavier profanity censored with bleeps. The kids will get angrier (and fouler) as their health depletes, until they finally give up on saving the town and go home.' FROM games WHERE igdb_id = 1257 ON CONFLICT (game_id, language_code) DO NOTHING;
