INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R4: Ridge Racer Type 4', 'R4: Ridge Racer Type 4 is the fourth game in the Ridge Racer series. It includes eight tracks (with reverse variants, for a total of 16 layouts) and 321 vehicles, all of which are fictional. This iteration was one of the first PlayStation titles to feature Gouraud shading on polygons, giving the game a visual depth that was previously missing. It was also the first Ridge Racer game on the system to feature two-player split-screen mode and offered two different driving models.' FROM games WHERE igdb_id = 18699 ON CONFLICT (game_id, language_code) DO NOTHING;
