INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchu: Stealth Assassins', 'Tenchu: Stealth Assassins is an action-adventure stealth game developed by Acquire and published by Sony Music Entertainment Japan in Japan and Activision worldwide for the PlayStation in 1998. Tenchu is known for its stealth gameplay and the eerie settings of feudal Japan. Tenchu was one of the first ninja games to incorporate stealth, a very crucial aspect of ninjutsu. However, aside from featuring traditional martial arts in battles, the game incorporates elements of historical fantasy and Japanese mythology. The game also used motion capture where actor/martial artist Sho Kosugi and his son Kane, were hired as actors for the game''s combat moves.' FROM games WHERE igdb_id = 4113 ON CONFLICT (game_id, language_code) DO NOTHING;
