INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisted Metal III', 'Twisted Metal III is a vehicular combat game released in 1998 for the PlayStation. Players control weaponized vehicles in arena-based battles, aiming to destroy opponents and survive each round. The game features new characters, levels, and a redesigned physics engine. It introduced a new developer, 989 Studios, following the departure of the original creators. Reception was mixed, with criticism focused on controls and design changes.' FROM games WHERE igdb_id = 4697 ON CONFLICT (game_id, language_code) DO NOTHING;
