INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakneck', 'Breakneck is one part racing simulation, one part car combat game. It was released for the PC in 1998 in Germany, and 2000 in North America. The game features so-called "spine-crushing speed". Your racing opponents are already waiting for you. Take up the challenge, equip your car with weapons and tools and win the races.' FROM games WHERE igdb_id = 78593 ON CONFLICT (game_id, language_code) DO NOTHING;
