INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Monster Capsule: Breed and Battle', 'Yu-Gi-Oh! Monster Capsule: Breed and Battle, frequently abbreviated "MCBB", is the first Yu-Gi-Oh! video game, released by Konami on July 23, 1998 for the Playstation. It features a more well-developed variant of the Capsule Monster Chess game from the manga. Monster Capsule: Breed and Battle is the only video game to feature Capsule Monster Chess, though Yu-Gi-Oh! Monster Capsule GB features a modified version of the game and many of the monsters from MCBB, and Yu-Gi-Oh! Capsule Monster Coliseum features the spinoff game Capsule Monsters.' FROM games WHERE igdb_id = 56980 ON CONFLICT (game_id, language_code) DO NOTHING;
