INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('game-de-seishun', 131320, '1998-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob45l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4z6s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game de Seishun', 'Game de Seishun is a multiplayer party board game in the mold of The Game of Life, which follows each player''s avatar through five stage of youth, from kindergarten through to graduating high school and starting a career. The focus is on building friendship and relationships with various characters, and living a full and satisfying youth, with the winners being decided by so-called "seishun points" which are accrued by deepening interpersonal relationships, earning money from jobs, exercising and studying to improve oneself, and going on dates. Each player moves through the board by selecting from one of several numbers to determine the number of spaces to move. Various spaces have different effects: some cause good or bad events to occur, some cause random events to happen, and some allow the player to pick a specific activity for the day such as studying or going to work which will increase various stats that in turn affect future events. Once all players have reached the goal, points are tallied based on the game type selected and a winner is decided.' FROM games WHERE igdb_id = 131320 ON CONFLICT (game_id, language_code) DO NOTHING;
