INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'California Speed', 'California Speed features racing through California, with a range of different and unique tracks based on the real life maps of the US state, with short-cuts and branching elements adding elements of strategy when racing to the finish line.The car pool includes the usual collection of fast cars, as well as F1 racers and golf-carts.' FROM games WHERE igdb_id = 3335 ON CONFLICT (game_id, language_code) DO NOTHING;
