INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Journeyman Project 3: Legacy of Time', 'The Journeyman Project 3: Legacy of Time is a sequel to The Journeyman Project and The Journeyman Project 2: Buried in Time. This final installment uses a 360° pre-rendered 3D CGI interaction system, similar to QuickTime VR. It featured impressive production values common for the series.' FROM games WHERE igdb_id = 11674 ON CONFLICT (game_id, language_code) DO NOTHING;
