INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heart of Darkness', 'Heart of Darkness places players in the role of a child named Andy as he attempts to rescue his dog who has been kidnapped by creatures known as The Dark Souls. The game has about half an hour of storytelling cinematic sequences, thousands of 2D animated frames, and uses pre-rendered background scenery. The game was supervised by game developer Éric Chahi, known for Another World, this time with a team of artists and developers. The game also features an original score by film and television composer Bruce Broughton. A Game Boy Advance port was announced in 2001 but it was never released.' FROM games WHERE igdb_id = 6433 ON CONFLICT (game_id, language_code) DO NOTHING;
