INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pinball-soccer-98', 66494, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6wog.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Soccer ''98', 'Pinball Soccer ''98 tries to break the mold by combining soccer and pinball. The game features two tables, one of which must be unlocked. You defend your own goal with your usual flippers. The goal at the other side is defended by four defenders and a goalie. If you complete objectives you are allowed to perform free kicks, corners and penalties. Referees can roam the playing field to kick back the ball to your flippers. It is possible to play this flipper game in two player mode, in that case both goals receive flippers and the goal becomes to score in one another''s goal.' FROM games WHERE igdb_id = 66494 ON CONFLICT (game_id, language_code) DO NOTHING;
