INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deathtrap-dungeon', 8470, '1998-03-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pvp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x9placxty748auzvnnjl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathtrap Dungeon', 'Built by a mad baron to bring notoriety to his town, only the brave or foolish would dare to enter Deathtrap Dungeon. Fabulous riches await the victor. Many adventurers have tried - none have come out alive… As Red Lotus, the alluring assassin, or Chaindog, the savage warrior, you must battle your way to the heart of the dungeon and slay the great dragon, Melkor, mightiest of all the beasts of the underworld. If you succeed, gold and glory will be yours. If you fail, your sole reward is death. A hellish horde of monsters await you in subterranean pits and passageways. A host of weapons, spells and charms are available - you will need them, for you are about to embark on a heart-stopping journey filled with brutal combat, deadly traps and the darkest magic.' FROM games WHERE igdb_id = 8470 ON CONFLICT (game_id, language_code) DO NOTHING;
