INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Divi-Dead', 'Considered one of the pioneers of the eroge genre, Divi-Dead is a horror themed visual novel blending over-the-top gore, graphic sex, and a complex, supernatural-themed storyline with multiple endings.' FROM games WHERE igdb_id = 12420 ON CONFLICT (game_id, language_code) DO NOTHING;
