INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild West Math', 'Wild West Math is an educational game designed to help students in grades 2–6 practice and improve core math skills. Through a variety of activities themed around the American Wild West, players work on addition, subtraction, multiplication, division, and long division. The game features colorful Western characters, adjustable difficulty settings, tutorial help screens, and progress tracking to accommodate a range of learning needs.' FROM games WHERE igdb_id = 133523 ON CONFLICT (game_id, language_code) DO NOTHING;
