INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Invaders', 'Seven friendly aliens land in a country town to go to a rock concert... But some people believe they''ve arrived to take over the planet! Anything can happen in this fun interplanetary story, narrated by Gustavinho, star of O Enigma da Esfinge. Have an instant seventh-grade contact with the 7 Invaders, an adventure full of galactically animated screens and otherworldly activities.' FROM games WHERE igdb_id = 293240 ON CONFLICT (game_id, language_code) DO NOTHING;
