INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get Bass: Sega Bass Fishing', 'Bass Fishing is an arcade fishing game where players attempt hook and reel in fish with different lures. Consisting of four stages at different times of the day, the player is expected to catch a certain weight of fish within a time limit before moving onto the next stage. The final stage allows only for one fish to be captured, but are among the largest in the game and most difficult to catch. Fish are measured under four weight classes: Small One, Average, Big One, and Huge.' FROM games WHERE igdb_id = 39462 ON CONFLICT (game_id, language_code) DO NOTHING;
