INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Dance', 'Addictive breakout-style action meets fast and furious arcade fun. With 100 levels, challenging end bosses and multiple power-ups, Dragon Dance is the game you can''t put down! Head-to-head combat with boss enemies every 10th level. Random events like earthquakes shake up the gameplay. Dragon control and length add to the complexity of each puzzle. Enjoy Vs. mode and play with friends via Game Link Cable.' FROM games WHERE igdb_id = 49940 ON CONFLICT (game_id, language_code) DO NOTHING;
