INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World League Soccer ''98', 'In World League Soccer ''98 the player is able to move, kick, chip, volley and perform advanced passing techniques, including one-twos, chip returns and swerved long-balls. Players can also chest and head the ball with total control. Also, it is possible to alter pitch type, weather conditions, and stadium design. There are eight major European leagues plus the US and Japanese leagues, with 145 teams available to choose from, as well as international competitions which can be custom-designed. Live commentary is provided by Peter Brackley and Ray Wilkins, and motion capture by Les Ferdinand.' FROM games WHERE igdb_id = 45466 ON CONFLICT (game_id, language_code) DO NOTHING;
