INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liath: WorldSpiral', 'Liath: WorldSpiral is a Russian-made point-and-click, third-person graphical adventure which involves talking to people, solving puzzles and general exploring. In this game, you play a modern-day magician named Criss looking for his friend, Tiche, who disappeared hundreds of years ago in a world known as Azeretus. In the ageless battle of "Good versus Evil", the story revolves around magic spells, curses, and spirits.' FROM games WHERE igdb_id = 69594 ON CONFLICT (game_id, language_code) DO NOTHING;
