INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golgo 13: Mienai Guntai', 'Golgo 13 - Mienai Guntai (Also known as Golgo 13 Kenenai Guntai) is the second Playstation one game based on the manga series written and illustrated by Takao Saito, published in Shogakukan''s Big Comic magazine since 1969. In 1976, the manga won the 21st Shogakukan Manga Award for general manga. The series follows the titular character, a professional assassin for hire.' FROM games WHERE igdb_id = 91930 ON CONFLICT (game_id, language_code) DO NOTHING;
