INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celtica', 'Celtica is a point and click adventure set on a tiny, mysterious, beautiful and extremely green island off the west Irish coast. The game begins with your character on a small hill near the tip of the island. Several exploratory paths are available to you, including a lighthouse, an abandoned church, and a cemetery. The Celtic theme is played to the full, you will be unable to avoid many stone circles, crucifixes or Celtic knots.' FROM games WHERE igdb_id = 71838 ON CONFLICT (game_id, language_code) DO NOTHING;
