INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero Zone', 'It’s the year 2098 in Megatown, a sprawling city populated by Bios and their slaves, the Cybers. Your father has just been killed and you have inherited his fortune as well as his company. Your mission is to help Agent Ripley find out who killed your father and why, journeying through outer space in search of the computer chip that will allow the sensual union between the Bios and Cybers.' FROM games WHERE igdb_id = 94692 ON CONFLICT (game_id, language_code) DO NOTHING;
