INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubblets', 'Based on the Japanese SameGame, Bubblets is a puzzle game in which the game-board consists of a screen of differently-colored balls arranged in a matrix. There are five different colors: red, blue, green, yellow and purple. The player then clicks on any two or more connecting similarly-colored balls to eliminate them from the matrix, earning an appropriate number of points in the process. The more balls eliminated at once, the higher the points added to the player''s score.' FROM games WHERE igdb_id = 298725 ON CONFLICT (game_id, language_code) DO NOTHING;
