INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backstreet Billiards', 'Backstreet Billiards is a unique pool simulation and offers you a variety of pool and carom modes: 8-Ball, 9-Ball, Rotation, Basic Pool, 141 Continuous, Bowlliards, Cutthroat, 5-9 and One Pocket. The special feature of this title is the story mode, which consists of an adventure in which you are on the search for your father''s cue and can pick up various objects.' FROM games WHERE igdb_id = 94359 ON CONFLICT (game_id, language_code) DO NOTHING;
