INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cardinal Syn', 'What began as a simple prophecy evolved into bloody war. A board of fantasy warriors in an epic story of a war-torn land. Battle it out with an arsenal of weapons including battle axes, broadswords, crossbows and more! Deadly interactive 3-D environments - dodge fire-pits, flying arrows and spike-lined walls forcing fighters to kill or be killed. 8 main characters with a further 10 hidden characters waiting to be unleashed!' FROM games WHERE igdb_id = 26657 ON CONFLICT (game_id, language_code) DO NOTHING;
