INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otto''s Ottifanten: Baby Bruno''s Nightmare', 'Baby Bruno has had nightmare! A magician has dissolved his Teddy Honk and he may never be seen again. Only you can help him to rescue the teddy bear. But for that you need Baby Bruno to enter the mysterious cylinder, where you will face nasty traps, obstacles and enemies. Plunge into the adventure and "crack" one level after another: Hike through a secret forest where every tree is an obstacle. Enter a castle full of trickery and pitfalls - and press forward into the dungeon where Honk is trapped.' FROM games WHERE igdb_id = 49042 ON CONFLICT (game_id, language_code) DO NOTHING;
