INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Soccer', 'Backyard Soccer is a sports game developed and published by Humongous Entertainment for the Windows and Macintosh operating systems. It is the second game in the Backyard Sports series and the first in the Backyard Soccer series. The game features a roster of 30 playable kids and allows the creation of custom-colored teams. Players can choose between single matches or a full season mode, which includes matches against various teams, including custom ones. A practice mode is available for learning the game’s kicking mechanics and penalty situations. Standard soccer rules, such as fouls and hat tricks, are implemented.' FROM games WHERE igdb_id = 50300 ON CONFLICT (game_id, language_code) DO NOTHING;
