INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Slam Turkey Hunt', 'It''s time to talk turkey! North America''s largest game bird awaits you in this 3-D hunting adventure. Bag the four major subspecies to achieve the Grand Slam. This is no easy game. The turkey''s finely developed survival skills, excellent sense of hearing, and remarkable 300-degree field of vision will challenge even the most experienced woodsman.' FROM games WHERE igdb_id = 46951 ON CONFLICT (game_id, language_code) DO NOTHING;
