INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rugrats Movie: Activity Challenge', 'The Rugrats Movie: Activity Challenge is an educational game based on the 1998 The Rugrats Movie, which in turn is based on the Daytime Emmy-award winning animated television series. The game features six games that can be played, each game has ten levels and a bonus level that can be accessed if a Cynthia doll is acquired during play.' FROM games WHERE igdb_id = 8088 ON CONFLICT (game_id, language_code) DO NOTHING;
