INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trespasser', 'Trespasser is a PC game released in 1998. Set one year after the events of the 1997 film The Lost World: Jurassic Park and published alongside the film''s home video release. The player assumes the role of Anne, the sole survivor of a plane crash on InGen''s Jurassic Park "Site B" on Isla Nublar. With a fractured arm and no equipment to speak of, Anne must escape the remote island by solving puzzles and evading dangerous dinosaurs.' FROM games WHERE igdb_id = 9057 ON CONFLICT (game_id, language_code) DO NOTHING;
