INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredible Coneman', 'The Incredible Coneman is a maze chase game developed by Lars Barstad and Per Ivar Pedersen unique for its 3d graphics, its death sound, and the three-second bass melody that loops infinitely. It was originally featured in issue 32 of the PSX ''Exclusive Demos'' series and made using the Net Yaroze development kit.' FROM games WHERE igdb_id = 262418 ON CONFLICT (game_id, language_code) DO NOTHING;
