INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Hunting: Trophy Whitetail', 'The first of the first-generation deer hunting games to offer complete freedom of movement, Trophy Whitetail uses a build-like engine to create fully explorable 3D (well, 2.5D) environments. Choose your weapon from an arsenal that includes a .357 magnum, a bow, a 7mm bolt-action rifle and a 30-30 lever-action rifle, and then choose your hunting location from either Oregon, New York, Arkansas or Kentucky and you are all set. You have in-game options to camouflage yourself, attract scent, etc. as well as a gps to show your position in the gameworld.' FROM games WHERE igdb_id = 70239 ON CONFLICT (game_id, language_code) DO NOTHING;
