INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Gunner: The Robot Wars', 'In a hellish mechanical future, the latest generation of robots are fighting a self-destructive war of attrition. Command your war machine in the hyper realistic 3D worlds. Power up your weapons. 15 missions and only one way to survive: destroy the enemy.' FROM games WHERE igdb_id = 144188 ON CONFLICT (game_id, language_code) DO NOTHING;
