INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy!', 'This version of Jeopardy features the digitized look and voice of the TV show''s host, Alex Trebek and even the announcer, Johnny Gilbert, as well. There are 650 different categories to choose from as well as 4,000 new answers. The player answers questions by selecting letters by using the analog or D-pad and will be given suggestion words to help them along. The same rules apply to the game as they do in the TV show, the game is divided into three different rounds: Regular, Double Jeopardy and Final Jeopardy and has three different contestants.' FROM games WHERE igdb_id = 3396 ON CONFLICT (game_id, language_code) DO NOTHING;
