INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Master', 'A Japanese fighting game with 3D character models released on PlayStation in 1998 and re-released on PlayStation under the Major Wave series label in 2000 by Hamster Corporation. The game has a straight forward combat system, 4 buttons with L1 and R1 combinations for a total of 12 moves. there is also an upgrade system for characters that unlocks more moves by using a move enough times in normal gameplay. The game has a total of 120 moves and there is apparently a robot character/mode that can learn moves by fighting other characters, or has access to all possible moves already unlocked, which can then be used for custom loadouts for PvP matches.' FROM games WHERE igdb_id = 86222 ON CONFLICT (game_id, language_code) DO NOTHING;
