INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimSafari', 'SimSafari brings Africa to you. Imagine yourself in rugged bush country, peering through binoculars at vast herds of elephants, zebras and lions. Choose from exotic plants and wildlife to create your own safari park. Team with a neighboring village and build a flourishing safari camp. Even tackle wild missions! Subtle mix between SimCity and an African Safari. For ages 8+.' FROM games WHERE igdb_id = 95477 ON CONFLICT (game_id, language_code) DO NOTHING;
