INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utopia', 'Utopia was a browser-based strategy game where each player manages a province within a kingdom, collaborating with other players to grow their territories and strengthen their kingdom. Players build and manage resources like food, housing, and military defenses on their land, and engage in real-time attacks and espionage against other provinces. The game emphasizes teamwork, strategic planning, and timing as players balance growth, defense, and warfare to lead their kingdom to dominance.' FROM games WHERE igdb_id = 312383 ON CONFLICT (game_id, language_code) DO NOTHING;
