INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laurie Anderson''s Puppet Motel', 'This is an interactive environment containing music, videos, monologues, and art-jokes from performance artist and musician Laurie Anderson with the help of designer Hsin-Chien Huang. It begins with an electrical outlet that glows and howls into the darkness. Then you enter "The Hall of Time", a corridor in the motel where icons cover the walls, and lead to 33 symbol-crowded rooms. A puppet Laurie Anderson sparingly appears as a guide.' FROM games WHERE igdb_id = 172408 ON CONFLICT (game_id, language_code) DO NOTHING;
