INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oriental Legend Super', 'Oriental Legend Super is a side scrolling fighting game produced by Taiwanese company I.G.S. in 1998. As an enahnced version of Oriental Legend, It adds new skills and removes some useless skills. In version 100, It was called Oriental Legend Special outside Asia. After version 100, It is named Oriental Legend Super/Xiyou Shi E Chuan Super.' FROM games WHERE igdb_id = 82749 ON CONFLICT (game_id, language_code) DO NOTHING;
