INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Napoleon Solitaire', 'Napoleon Solitaire is a shareware solitaire suite containing twenty-one variations on Forty Thieves solitaire also known as Napoleon at St Helena, Roosevelt, San Juan.  The basic game is played with two decks of cards. It has eight foundations where cards are built upwards by suit from ace to king and ten stacks of four cards ( this is where the forty thieves name originates.' FROM games WHERE igdb_id = 132169 ON CONFLICT (game_id, language_code) DO NOTHING;
