INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super ACiD Block Attack', 'Super ACiD Block Attack is a puzzle game, probably one you have seen before. The idea is to try and make solid-horizontal rows using the pieces that are given to you. You can rotate the pieces before they fall down to the bottom of the screen. You can make more than 1 row at a time, but only up to five.' FROM games WHERE igdb_id = 82459 ON CONFLICT (game_id, language_code) DO NOTHING;
