INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hard-truck-road-to-victory', 28143, '1998-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wuu9skh6szzhtl7ozdwx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xxmwrzwwc30qjlu2btmr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Truck: Road to Victory', 'You can choose to race with other tracks in two or three simple tracks, and there is a mode where you can just drive a truck to deliver cargo to your designated location. The second mode might be bit boring, since you do nothing but drive a truck and do nothing more, but it''s worth it for two reasons - primarily the extremely beautiful landscape you drive through. It is designed with the utmost care and detail and you can really feel like you''re really there. And secondly, the game simulates the job of a truck driver pretty accurately. While driving, you get to experience what a real truck driver feels and does on the road. Now, multiply that by a 1000 miles. But mostly, this is a truck racing game. You can change the view from behind the wheel to outside of the truck, whatever you like. There is also a good rearview mirror that helps you while driving. Overall, this is a fantastic truck simulation and racing game and you should try this one and the games sequels, Hard Truck 2 and the rest of the game''s series.' FROM games WHERE igdb_id = 28143 ON CONFLICT (game_id, language_code) DO NOTHING;
