INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon GBC', 'Harvest Moon GBC is a remaster of the Game Boy game Harvest Moon GB. It was released for the Game Boy Color by Natsume in North America and Nintendo in Europe. In the game, you''ll take care of your farm within the in-game year. The game has Game Boy link support where you can trade items with other owners of the game. The game is viewed from a bird''s eye perspective.' FROM games WHERE igdb_id = 220737 ON CONFLICT (game_id, language_code) DO NOTHING;
