INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Memory Madness', 'Mario''s Memory Madness was a browser game that was playable on the official Mario Party website. Unlike future promotional web games published by Nintendo, both Mario''s Memory Madness and Wario''s Whack Attack were made in Adobe Director instead of Flash and required the Adobe Shockwave 7.0 plug-in.' FROM games WHERE igdb_id = 231600 ON CONFLICT (game_id, language_code) DO NOTHING;
