INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megami Ibunroku Persona Digital Collection', 'A collection of minigames during a festival set after the events of Megami Ibunroku Persona. The minigames include races, quizzes, fortune-telling, an art gallery, puzzles, karaoke, air hockey, a shuffle game, and a shooting gallery. With other features like a sound player, persona compendium, music videos with remixed songs, and dress-up.' FROM games WHERE igdb_id = 263596 ON CONFLICT (game_id, language_code) DO NOTHING;
