INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Chaos', 'Castle Chaos is a turn-based fantasy adventure game where you guide one of four heroes through a chaotic castle. Your goal is to reach the treasure room in the center of the castle, grab as much gold as you dare, and make it safely to the outside. But this task is not an easy one; the castle''s passageways are different every game, there are traps to catch the unwary, and a deadly horde of minions is on the prowl. As if all that weren''t enough, the treasure chamber is patrolled by the evil wizardess herself.' FROM games WHERE igdb_id = 139156 ON CONFLICT (game_id, language_code) DO NOTHING;
