INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('total-drivin', 44871, '1998-10-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ye5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total Drivin', 'Total Drivin is a racing game with five different classes of cars (4x4 Buggies, Dakar Rally, Sports, Indy and Rally) in six different locations (Moscow, Easter Island, Scotland, Hong Kong, Egypt and Switzerland). Each location has six different tracks to master with a total of 36 tracks. The different tracks actually are variations of the same track only slightly different. For example drive with different car type, reverse direction, ramps added or safety rails removed, different weather conditions etc. You can choose to drive with 1 of 8 different teams, each with different driving behaviour, providing 40 cars in total. There is multiplayer for 2 to 4 players, using split-screen and a link cable. The game also features typical 1990''s rave music. When your car rolls over the game will turn you right side up again, but if your car drives into water or falls into lava the game instantly ends.' FROM games WHERE igdb_id = 44871 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 44871 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
