INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Heat', 'Chaos Heat is a co-op shooter with beat ''em up elements released by Taito for arcades in 1998. It was the first game released for Taito''s G-Net arcade system. There are 3 characters to choose from with different stats and weapons, they all have an invincible dodge roll and a melee attack combo if close to enemies. The game has 5 stages that are made of multiple arenas which usually require a key card hidden on an enemy to progress, There are also objectives that split the path leading to different bosses and locations, though the final stage doesn''t change.' FROM games WHERE igdb_id = 122943 ON CONFLICT (game_id, language_code) DO NOTHING;
