INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brunswick Circut Pro Bowling', 'Choose from one of the 13 genuine tournament bowlers, with real lanes, real player animations, real lane conditions and changes, real bowling balls (genuine Brunswick!) each with its physical properties. All the tournament rules are available along six game modes (Exhibition, Skins —the Brunswick "Skins" game—, Tournament, Career, Practice, Cosmic). The playing character is picked from the Brunswick ProStaff or self-created by the player.' FROM games WHERE igdb_id = 44805 ON CONFLICT (game_id, language_code) DO NOTHING;
