INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Fútbol Selección Española ''98', 'Dinamic''s famous saga also have an own game dedicated to the 98''s World Cup celebrated in France. The first thing that claims your attention of the game is the data base, a great compilation of all competition international players and coaches, and also, all the stadiums where the matches will be disputed.' FROM games WHERE igdb_id = 78273 ON CONFLICT (game_id, language_code) DO NOTHING;
