INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RedCat: De Brutale Bankroof', 'Brutus and Max have robbed a bank. With the money they want to buy a lot of cheese and bones. On the way to the DogRock, an asteroid punches a hole in Brutus and Max''s spaceship, scattering all the money through space. RedCat is going after the money.' FROM games WHERE igdb_id = 201297 ON CONFLICT (game_id, language_code) DO NOTHING;
