INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Pony: Friendship Gardens', 'Raise and care for your own Little Pony. Gameplay is divided between the farm, where you care for your pony, and Pony Village, where you can play games. Along the way, you can teach her to jump fences, play games with other Ponies, and eventually cross the rainbow to Ponyland. But don''t let her rainbow fade away!' FROM games WHERE igdb_id = 108154 ON CONFLICT (game_id, language_code) DO NOTHING;
