INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rakugakids', 'Rakuga Kids is a 2.5D fighting game created by Konami for the Nintendo 64, released in 1998. The name Rakugakids is a portmanteau of the Japanese word rakugaki (a doodle), and kids, a reflection of the visual style of the game which resembled children''s drawings.' FROM games WHERE igdb_id = 3581 ON CONFLICT (game_id, language_code) DO NOTHING;
