INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fisher-Price: Big Action Construction', 'Fisher-Price Big Action Construction is an activity center game released on September 17, 1998. It is Funnybone''s take on Tonka Construction. In the game, the player can visit different work areas of the Big Action Construction Site. Collector Cards are rewarded for playing the actives. Obtaining all the collector cards in an activity will reward the player a certificate. One all six are completed, the player is declared a "number-one construction worker".' FROM games WHERE igdb_id = 324764 ON CONFLICT (game_id, language_code) DO NOTHING;
