INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melon Chan''s Growth Diary', 'Melon Chan''s Growth Diary (Japan: Melon-chan no Seichouki) is a Life simulation game it is comparable to Tamagotchi and other virtual life simulations. In Melon Chan''s Growth Diary the player raises and nurtures little girl Melon Chan. The games was only released in Japan and was one of the earliest titles released for the Neo Geo Pocket. The game was released for the Neo Geo Pocket and features monochrome graphics; however the Neo Geo Pocket Color is backwards compatible with the game.' FROM games WHERE igdb_id = 47622 ON CONFLICT (game_id, language_code) DO NOTHING;
