INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ares', 'Ares is a sci-fi real-time strategy action game developed by Nathan Lamont from Bigger Planet Software and published by Changeling Software in 1998 for Mac OS 9. Nathan didn''t earn any profit from the sales of the game, due to Changeling''s poor marketing. Changeling Software became defunct later that year, so Nathan modified Ares and re-released it as shareware by Ambrosia Software in 1999. Thanks to Ambrosia''s marketing efforts, the game became successful and reached its peak in the late 1990s. In 2008, Nathan Lamont released the original source code to Ares under the GNU GPL 2.0, and most of the media under the CC Attribution-Noncommercial-Share Alike license. This has produced Antares, which is a port of Ares for Mac OS X and Linux.' FROM games WHERE igdb_id = 93968 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 93968 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 93968 AND c.slug = 'ambrosia-software' ON CONFLICT DO NOTHING;
