INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancient-evil--1', 217854, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7qex.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scixly.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Evil', 'The Crypt of the Ancients was built 500 years ago, with the finality of offering a place for rest to the Ancients, who are the supposed creators of the world, and no one, but two exceptions, got to come out of it alive. Alaric, a mysterious and restless man, and one of the two fortunate people that got the mentioned achievement, has converted the crypt in his particular shelter . From there, he challenges the world by offering a reward of 50.000 gold coins to whom can penetrate into the place and coming out alive to tell the carefully kept secret. For centuries, many would-be heroes tried to uncover these secrets with no success, because the powerful spirits living inside the crypt ended the lives of those who try to defy them. To warn the incautious people who feel with strength, capacity and courage to assume the challenge of Alaric, it emerges the spirit of Jetraal the Heroic, who died three centuries ago in mysterious circumstances and was the other one who escaped alive from this restless place. His mission is to warn any person who tries to assume the risk that it is an adventure sentenced to failure in advance, as well as to annul the malicious instincts of Alaric. "Ancient Evil" is a 3D role playing game that uses high resolution graphics in a completely interactive environment, which provides it intensity and helps to wrap the player immediately. The people who plays this game introduce themselves into a story of magicians, mystic arts and illusions where there´s no lack of hand to hand combats and incantations.' FROM games WHERE igdb_id = 217854 ON CONFLICT (game_id, language_code) DO NOTHING;
