INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bananas in Pajamas: It''s Fun Time', 'Children join B1 and B2 on a wonderful adventure through the fun-filled world of Cuddles Avenue. With spectacular 3-D graphics, songs, and the Bananas humour, children will have fun as they develop important learning skills such as critical thinking, pattern recognition, and environmental awareness.' FROM games WHERE igdb_id = 221980 ON CONFLICT (game_id, language_code) DO NOTHING;
