INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XS Junior League Dodgeball', 'XS Junior League Dodgeball is designed to provide a fun, pick-up-and-play adaptation of the favorite gym-class activity, with colorful graphics and accessible gameplay for the whole family to enjoy. The game has, 8 different characters (male & female ones) & 2 game modes: - Tournament mode - VS Mode' FROM games WHERE igdb_id = 43943 ON CONFLICT (game_id, language_code) DO NOTHING;
