INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocky-mountain-trophy-hunter', 49946, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rflejmxc07exjlsfx92f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6e6h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocky Mountain: Trophy Hunter', 'If you''ve got a keen eye and a quick trigger finger, you might just have what it takes to become the next great hunter. Using a wide array of weaponry that ranges from rifles to bows to muzzleloaders, you''ll search all sorts of scenery in pursuit of your prey. Journeying through the treacherous mountains of Colorado, deep into the expanses of Montana, and through the deserts of New Mexico, you''ll have to keep your eyes peeled if you want to get the jump on these wily critters. There are plenty of animals out there, but each has realistic movements and behavior to evade your efforts. The big game creatures at large include deer, bighorn sheep, elk, and bears. Of course, you''ll have access to the requisite calls, attractants, and cover scents, but don''t expect any of these intelligent beasts to fall right into your traps. You''ll have to use your brains, reflexes, instinct, and some basic perseverance to help bag you a trophy kill. In ROCKY MOUNTAIN TROPHY HUNTER, you won''t have to worry about strapping a dead animal to your car roof!' FROM games WHERE igdb_id = 49946 ON CONFLICT (game_id, language_code) DO NOTHING;
