INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris 64', 'Tetris 64 is a puzzle game for the Nintendo 64. It was released only in Japan in 1998 despite the whole game being in English. It is the only Nintendo 64 game that can make use of the Nintendo 64''s bio-sensor which was included with the game.' FROM games WHERE igdb_id = 3346 ON CONFLICT (game_id, language_code) DO NOTHING;
