INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mercenaries of Astonia', 'A massively multiplayer online role playing game. Each player begins their journey as a battle-hardened Templar, a magic-wielding Harakim, or a dabbler of both, a Mercenary. The experience gained as characters solve quests, discover new places, and kill evil monsters, can be applied to raise any of a large number of attributes, skills and spells. Characters gain rank and power, qualifying them for better and more powerful equipment for the new and greater challenges that lie ahead.' FROM games WHERE igdb_id = 115487 ON CONFLICT (game_id, language_code) DO NOTHING;
