INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie Jewelry Designer', 'Barbie helps you design all kinds of jewelry that you can wear. Mix and match colors, patterns, and pretty designs. Print favorite designs on the Print ''n Shrink material using an ink-jet printer, then simply cut them out and bake them in an oven. They miraculously shrink into colorful plastic jewelry.' FROM games WHERE igdb_id = 200597 ON CONFLICT (game_id, language_code) DO NOTHING;
