INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-2ndmix', 94746, '1998-03-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bza.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dib.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania 2ndMix', 'Beatmania 2ndMIX is a rhythm game developed by Konami. It is the second game in the beatmania series and is part of the BEMANI franchise ( which it was named after: BEatMANIa ). The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. Beatmania 2ndMix is the first time the hidden modifier was included, which hides notes halfway down the screen. The Difficulty levels have been reworked to a scale between 1 and 6. All songs from the first game moves on, combined with some remixes and 13 totally new songs for a total of 25 tracks to play.' FROM games WHERE igdb_id = 94746 ON CONFLICT (game_id, language_code) DO NOTHING;
