INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardian''s Crusade', 'Guardian''s Crusade, known in Japan as Knight & Baby, is a 1998 role-playing video game (RPG) for the PlayStation, developed by Tamsoft and released worldwide by Activision. The game revolves around a warrior named Knight, his fairy friend Nehani, and a pink creature named Baby that the player raises and feeds like a virtual pet. The gameplay is that of a standard turn based RPG with non-random encounters. Guardian''s Crusade did not enjoy commercial success but received positive reviews.' FROM games WHERE igdb_id = 22835 ON CONFLICT (game_id, language_code) DO NOTHING;
