INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty: White Present', 'Hello Kitty White Present is an platformer Playstation game. The story begins when a earthquake happens in Monkey kingdom and destroys the castle, when that happens two little monkeys decide to go to Kitty''s house and ask for help. The game begins in Hello Kitty''s house attic and then the adventure will go to places like the Fairy in the Deep Forest, amusement parks, etc.' FROM games WHERE igdb_id = 284433 ON CONFLICT (game_id, language_code) DO NOTHING;
