INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neo-geo-cup-98-plus-color', 43976, '1998-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p0okhk42n2unaqw6jvnz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neo Geo Cup ''98 Plus Color', 'Wherever you go. Wherever you like. Its Kick Off Time! Easy! Simple! And Exciting! NeoGeo Cup ''98 Plus is a soccer game for the Neo Geo Pocket. The game features single match play, head-to-head play (using a link cable), and story mode. You can choose to play one of 16 international teams. Each team has their own collective stats. On the field you can perform passes, shots, dribbles, slidings and charges. In the story mode you have to win as many matches as possible in a series of tournaments. Before and during matches you can change the field formations and switch players. Each won match gives you prize money, this can be used to buy items for your team. These items usually improve one stat, but decrease another.' FROM games WHERE igdb_id = 43976 ON CONFLICT (game_id, language_code) DO NOTHING;
