INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('extreme-snow-break', 43791, '1998-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5mvv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dtuivpeip1kiezzsqjnd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Snow Break', 'Extreme Snowbreak is a ski/snowboard game. In one- or two-player or versus modes, with skis, a snowboard or a snowscoot, the goal of the game is to be the first to reach the finish line, in one piece if you can. All the components of extreme games are in Extreme Snowbreak: incredible speed, amazing jumps in the forest, between pylons or near precipices, Extreme Snowbreak is a game for speed addicts.' FROM games WHERE igdb_id = 43791 ON CONFLICT (game_id, language_code) DO NOTHING;
