INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Taxi M-12', 'Try to clear the course as fast as you can! Drive the crazy taxi down the course and score points by crashing into the cars with the correct number on them. Each course will give you a number that determines which cars to hit. You can only score when you crash into a car that is a multiple of the given number. Each course looks for multiples of different numbers, so you’ll want to study up on your times tables!' FROM games WHERE igdb_id = 313540 ON CONFLICT (game_id, language_code) DO NOTHING;
