INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Traffic Controller', 'Air Traffic Controller is a simulation computer game series, developed by TechnoBrain, that simulates the operation of an airport. The games simulate the job of an air traffic controller. The player''s mission is to direct planes onto the correct ILS, land them on the runway, taxi them to the correct gate, and to direct takeoffs.' FROM games WHERE igdb_id = 125618 ON CONFLICT (game_id, language_code) DO NOTHING;
