INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Music', 'Hopsalot, the Jump Start bunny, is showing off his Great Grandrabbit''s gramophone, when he is suddenly pulled right into the gramophone''s trumpet and into the Land of Music, hot on the trail of a batch of sour notes. It appears that the evil Sir Sournote has soured all the music; Hopsalot must travel throughout the Land of Music collecting all the ruined notes in his bag, and bring them to the Concert Hall to sweeten them again.' FROM games WHERE igdb_id = 72290 ON CONFLICT (game_id, language_code) DO NOTHING;
