INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wetrix', 'A rainstorm so fierce, it will keep you from leaving your home for the next six months. Using randomly shaped 3D blocks as they fall from the sky, you must create a series of lakes and dams before the heavy rains appear. Because if the water drains, you lose! Sound simple? Well, mix in a few natural disasters and bomb attacks, and suddenly you need to muster all your strategy and skill to combat nature''s fury!' FROM games WHERE igdb_id = 3637 ON CONFLICT (game_id, language_code) DO NOTHING;
