INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Monsters Stadium', 'Pokémon Stadium is the first game of the Pokémon Stadium series. It was released exclusively in Japan. The game focuses mainly on battling. Upon start-up, the game asks if the player if they want to use the Pokémon in their Game Boy Game Pak. If not, only Battle Mode can be accessed.' FROM games WHERE igdb_id = 47734 ON CONFLICT (game_id, language_code) DO NOTHING;
