INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neo-geo-cup-98-the-road-to-the-victory', 39529, '1998-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4akf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neo Geo Cup ''98: The Road to the Victory', 'Neo Geo Cup ''98: The Road to the Victory is a soccer video game based on the FIFA World Cup 1998, despite being released after the 1998 FIFA World Cup. It features 73 teams countries. Each team enters a "Regional Qualifying Round Final" where it plays a team it actually played in the 1998 FIFA World Cup qualification. For example: Spain would face Yugoslavia, an opponent it actually faced in its qualifying group. Or Italy would face Russia, an opponent Italy faced in the UEFA play-offs. If the player wins the opponent, it goes to a group much like the real life World Cup. In fact, the team faces opponents that were actually in its group. For Example: Mexico would face the Netherlands, Belgium and South Korea. It is a re-make of Super Sidekicks 3. However, animations and designs were exactly the same. The only difference is teams to reflect the World Cup, Kits again to reflect the World Cup, and players to resemble squads from the World Cup (Teams that did not qualify use line-ups from friendly games and qualifiers). It''s slogan is "We got the kick". Unlike its arcade counter-part, the Neo Geo version tries to be more of a soccer simulation game. Differences include the Neo Geo version more slowed down, and more realism added in shooting, passing, etc.' FROM games WHERE igdb_id = 39529 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39529 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
