INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('max-power-racing', 251135, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6jx2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max Power Racing', 'Max Power Racing is a racing simulation game. It is licensed by the UK magazine Max Power. It features cars from various manufacturers. It features 31 tracks across 11 countries from all over the world, featuring cities, mountain roads as well as off-road tracks. You can play in arcade mode (to unlock tracks), player mode and championship mode. Player mode allows you to play against a friend or set personal records and in championship mode you play through all tracks. There are four difficulties to select from in the championship mode. You start with the lowest, but finishing first gains you points with which you can unlock the other difficulties and new and better cars to race with.' FROM games WHERE igdb_id = 251135 ON CONFLICT (game_id, language_code) DO NOTHING;
