INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astra Superstars', 'A one-on-one 2D fighting game, Astra Superstars pits all the champions of the magical kingdom against each other in a series of 3-round fights to earn the right to challenge the evil Satan Volte and try to put an end to his reign of terror. Seeing as how all the fighters have magical abilities, the fights take place in mid-air, allowing you and your opponent to fly all over the arena while you try to defeat each other using your basic attacks, special moves (triggered by specific controller motions) and super attacks.' FROM games WHERE igdb_id = 39603 ON CONFLICT (game_id, language_code) DO NOTHING;
