INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MiG-29 Fulcrum', 'The Mikoyan-Gurevich MiG-29 Fulcrum is one of the world''s most maneuverable and toughest fighter jets and has often been compared to its closest Western counterpart, the F-16. Innovations unique to the aircraft allow MiG pilots to perform remarkable moves like the Tailslide and Cobra maneuvers.' FROM games WHERE igdb_id = 229931 ON CONFLICT (game_id, language_code) DO NOTHING;
