INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Game Show', 'Ready "to boldly go where no man has gone before?" So you think you know all about Star Trek? Like to amaze your friends at parties by listing the girlfriends of Captain Kirk in order? Then you''ve come to the right place! Whether you''re a casual or hard-core Trekker, you can explore hundreds of questions on your favorite moments from the Star Trek universe, in an irreverent game show setting with Q as your sardonic host. Personnel, planets, aliens, anomalies - The Game Show covers all quadrants of the galaxy, from the original voyages of the Starship Enterprise to the deep space journeys of the U.S.S. Voyager, plus all the movies.' FROM games WHERE igdb_id = 69228 ON CONFLICT (game_id, language_code) DO NOTHING;
