INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xtreme Rally', 'Xtreme Rally, known as Off Beat Racer! in Japan, is a 3D off-road racing game developed and released by SNK for for Hyper Neo Geo 64 hardware on May 13, 1998 Just like Roads Edge, each track features loops on both endpoints, causing a two-way road that can lead to head-on collisions. Up to four cabinets can be linked up for multiplayer support.' FROM games WHERE igdb_id = 28136 ON CONFLICT (game_id, language_code) DO NOTHING;
