INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakai-ou: King of Crusher', 'You are a Japanese salary man, normal in every way... except that you''ve just been bitten by an evil space insect, turning you from a regular man into a rage-fueled monster. Destroy anything you can to fill your dopamine gauge, and reach the end of the stage to continue your transformation from a normal human into an enormous kaijuu monster, all the while avoiding the police and the military trying to stop you.' FROM games WHERE igdb_id = 65147 ON CONFLICT (game_id, language_code) DO NOTHING;
