INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fisherman''s Bait: A Bass Challenge', 'Fisherman''s Bait brings the simple fishing gameplay of the original arcade title to the Playstation. Reel in 6 different fish like the Rainbow Trout and Largemouth Bass using 7 kinds of lure. Once you get a bite, drag your catch by pressing buttons in alternating fashion. Challenge Tournament mode and catch as many fish as you can in the set time limit!' FROM games WHERE igdb_id = 22845 ON CONFLICT (game_id, language_code) DO NOTHING;
