INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arrival, or Attack of the B-Movie Clichés', 'You''re an eight year-old kid, stuck washing dishes in the kitchen instead of watching "Captain Dangerous" on television. Life''s not fair. But then, oh man, a spaceship lands in your backyard! From outer space! Forget the dishes—this is way too cool to ignore.' FROM games WHERE igdb_id = 314038 ON CONFLICT (game_id, language_code) DO NOTHING;
