INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-custom-car-designer', 313290, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8o25.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctm15.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Custom Car Designer', 'Mattel Media''s Hot Wheels Custom Car Designer CD-ROM puts you or your child behind the virtual wrench, spray brush and stamp pad, allowing you to customize the appearance of 20 different traditional Hot Wheels models (including the jeep, speedboat, blimp and a number of racers). But why stop at detailing your dream machine when you can also draft licenses and traffic tickets, label trophies and ribbons, and create flags and license plates? From the main access screen, you can visit the Print Shop to create a newsletter, greeting cards, business cards, letterhead, and postcards; the DMV to make licenses and license plates and issue tickets; Victory Lane for ribbons, trophies, banners, and flags; and the Customizing Garage where you customize your cars. The customization features include choosing the colors for your car from eight available, placing decals and adding different styles of tires, muffler pipes, spoilers, and weapons. Licenses, ribbons, and trophies can be personalized including imported photos for licenses. Also, traffic tickets can be created using traditional violations or personalized to include "special violations," such as "Dad didn''t take me to the movies...$20 fine." Everything you create can be saved and printed. Hot Wheels Custom Car Designer CD-ROM sports a basic point-and-click interface and has no demanding PC requirements. Anyone familiar with MS Paint will be able to make use of the variety of creativity applications. Geared towards children, the product includes voice-recorded online help and links to the Hot Wheels Web site. No longer must you pine over your inability to tweak, tune or trick out your own car or truck; Hot Wheels Custom Car Designer CD-ROM puts all the tools at your disposal for making your souped-up fantasy car into a (virtual) reality.' FROM games WHERE igdb_id = 313290 ON CONFLICT (game_id, language_code) DO NOTHING;
