INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('josephine-at-school', 204784, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ven.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Josephine at School', 'Josephine at School is an educational puzzle game for children. This full-length game is created in cooperation with educationists to give the activities a perfect mix of play and learn. This game is good for children who like to learn new letters and numbers. In the letter section you can play lotto with Josephine. You should either pair capital letters or lower-case letters. Or you can match the right letter with the right picture. You also find fun memory games, connect the dot puzzles and you can learn more about the Nordic countries, seasons and a lot more.' FROM games WHERE igdb_id = 204784 ON CONFLICT (game_id, language_code) DO NOTHING;
