INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lets-go-read-an-ocean-adventure', 313376, '1998-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8o79.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctmaf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Go Read: An Ocean Adventure', 'Robby Raccoon and Emily Squirrel are on a mission to find the missing book mobile under the ocean. Along the way they find lots of things to do. At Pier City there is a stingray that paints long and short vowels. Kids hear the sounds vowels make and then hear words and sentences that use the sounds. Young readers then use what they learned to deliver mail. The postcards and packages have vowel sounds and words. At the Powerstation kids put letters together to sound-out words. This is a great phonics activity. Kids hear all the letters sounded out as they form words. Children also blend bubbles to make words with consonant blends, find words with a target blend or digraph sound and find books under the sea. Once children find storybooks they can hear them read aloud or record themselves reading the story and play it back. Kids will love playing these activities and parents will agree for learning phonics the Let''s Go Read series is remarkable.' FROM games WHERE igdb_id = 313376 ON CONFLICT (game_id, language_code) DO NOTHING;
