INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced V.G. 2', 'Advanced Variable Geo 2 is one of several titles in the long-running all-girl fighting game series. Using one of 12 characters, including nine returning from the previous title, the player can choose from a variety mode, including a standard arcade mode, a story mode, a 2-player versus mode, and a time attack mode. There is also a practice mode, a wide variety of game options, and play statistics tracking.' FROM games WHERE igdb_id = 44799 ON CONFLICT (game_id, language_code) DO NOTHING;
