INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Cup ''98 France: Road to Win', 'World Cup ''98 France: Road to Win, not to be confused with FIFA Road to World Cup 98 is a football game released for the Sega Saturn. World Cup ''98 France recycles its core engine and much of its content from earlier Sega-published football games, particularly Sega Worldwide Soccer 98. This is the last Saturn football game whose lineage can be traced back to 1995''s Victory Goal. The next game in the series, Sega Worldwide Soccer 2000 was built from the ground-up by Silicon Dreams for the Dreamcast.' FROM games WHERE igdb_id = 271931 ON CONFLICT (game_id, language_code) DO NOTHING;
