INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Games: Pro Boarder', 'X-Games: Pro Boarder is a snowboarding game with several game modes including downhill and half pipe. In downhill mode the player''s mission is to get down as quickly as possible, also grinding on several objects like cars and airplanes that have been placed in the scenery. In half pipe mode the player must travel from the beginning to the end of the pipe doing stunts on the left and the right, finishing before the time reaches zero having as many points as possible.' FROM games WHERE igdb_id = 44844 ON CONFLICT (game_id, language_code) DO NOTHING;
