INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hardwar', 'On the barren moon Titan, within the city of Misplaced Optimism, scavenger operators and ram-runners fight for the right to courier the last of Titan''s worthless riches. Caught between the powerplays of neo-feudal corporations and mutant underworld cartels, there is only one escape. Off-planet. ...You''re going to need all the Hardwar(e) you can get.' FROM games WHERE igdb_id = 19566 ON CONFLICT (game_id, language_code) DO NOTHING;
