INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Golf Pro', 'The Golf Pro is Empire Interactive''s first foray into golf sims. It is a standard 3rd person golf simulation with the addition of the mouse drive system introduced on Maxis''s SimGolf and popularized on Sierra''s Front Page Sports: Golf. Essentially what this system does is replace the swing bar and use a series of mouse movements and clicks to determine the power, accuracy and direction of the swing.' FROM games WHERE igdb_id = 85914 ON CONFLICT (game_id, language_code) DO NOTHING;
