INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars Trilogy Arcade', 'Star Wars Trilogy Arcade is an arcade game first released in 1998. The game is a 3-D rail shooter based on the original trilogy of Star Wars films and was released along with the special editions of these films. Sega also released an accompanying pinball game. The game is not to be confused with Star Wars Arcade, another Star Wars game released to arcades by Sega in 1993.' FROM games WHERE igdb_id = 39351 ON CONFLICT (game_id, language_code) DO NOTHING;
