INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fox Sports College Hoops ''99', 'Complete college basketball license featuring over 120 college teams. NCAA Tournament, NCAA Sweet 16 and Final Four. Pre-season and Conference tournaments. In-depth player attributes and skill ratings. Three difficulty levels, easy to learn controls, and multiple camera angles. Authentic college basketball look and feel with real logos, uniforms and home courts, and real college offensive and defensive plays.' FROM games WHERE igdb_id = 3498 ON CONFLICT (game_id, language_code) DO NOTHING;
