INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titenic', 'Titenic is a Famicom beat-em-up based off of the 1997 film Titanic by ex-Hummer Team members. This game was hacked to create the more well-known Harry''s Legend. The game was most probably first known to be on an ABAB 3-in-1 multicart and was later found on a 15-in-1 separated into two separate games.' FROM games WHERE igdb_id = 10841 ON CONFLICT (game_id, language_code) DO NOTHING;
