INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maid in Heaven: Ai to Iu Na no Yokubou', 'The protagonist has a dream to have a maid someday. One day, his childhood friend, Nagisa, visits him. When they were children, he told Nagisa that he liked maids. Nagisa remembered his words and came to him as a maid. Finally his dream came true and he begins to enjoy his night life with her...' FROM games WHERE igdb_id = 260823 ON CONFLICT (game_id, language_code) DO NOTHING;
