INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rival Realms', 'The game has three races to choose from: Humans, Elves, and Greenskins. Each race has its own characteristics and units just as is found in most RTS games. However, that''s just the beginning. Your armies are always unique. Every single unit can gain up to five levels of experience and has its own inventory that can be traded between units. Inventory items include skill artifacts, keys, potions, spell scrolls, and more.' FROM games WHERE igdb_id = 70472 ON CONFLICT (game_id, language_code) DO NOTHING;
