INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Truck Madness 2', 'Players can race all the big name monster trucks such as Big Foot and Gravedigger as well as new custom WCW and NWO trucks. Along with classic lap and point-to-point races, there are a variety of multiplayer king of the hill and monster truck rally events.' FROM games WHERE igdb_id = 3542 ON CONFLICT (game_id, language_code) DO NOTHING;
