INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokimeki Memorial Drama Series Vol. 2: Irodori no Love Song', 'Tokimeki Memorial Drama Series vol. 2: Irodori no Lovesong is a visual novel spin-off game of the original Tokimeki Memorial. Irodori no Love Song focuses on Ayako Katagiri, with the player trying to compose a new song in time to win the school festival''s band contest.' FROM games WHERE igdb_id = 108751 ON CONFLICT (game_id, language_code) DO NOTHING;
