INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Paint: Paintball 2', 'Digital Paint: Paintball 2 is a free game that was originally a Quake 2 mod. The game is a fast-pasted multiplayer first-person shooter with single shot eliminations and has several game modes including CTF, Siege, KOTH, DM, TDM, and Elimination.' FROM games WHERE igdb_id = 67950 ON CONFLICT (game_id, language_code) DO NOTHING;
