INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Patrick Polly Swooshball Challenge', 'The Patrick Polly Swooshball Challenge is a game with a mix of Pong and Tennis. The game concept is based on a major commercial campaign by Candelia, one of the leading candy manufacturers in Scandinavia. Released as freeware, people had to send in 5 scanned barcodes from bags of Polly in order to receive the game.' FROM games WHERE igdb_id = 186748 ON CONFLICT (game_id, language_code) DO NOTHING;
