INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('v-ball-beach-volley-heroes', 72234, '1998-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8gn2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tt9e5a3tzmit8g1xztio.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Ball: Beach Volley Heroes', 'V-Ball - Beach Volley Heroes is the sequel to the NES game Super Spike V''Ball, an arcade game that deals with beach volleyball in a very special way. There are several teams you can choose from, such as Soldiers, Ninjas, Soccer players and so on, and each of them has got its own moves and special effects. There are commands for both heavy shots and for light ones, making you choose the strength to hit and throw the ball. There are no power bars and once hit, the ball flies to the opposing side automatically. The special moves can be triggered whenever you push certain button combinations (triangle and circle, circle and cross, etc) at the right moment. If it is a defense move, for instance, you must do it in response to others attacks. There is a Tournament mode, which is the main solo entertainment (although you can also play single matches vs the AI), but this game is clearly designed around player-vs-player mode, for arcade matches against human opponents.' FROM games WHERE igdb_id = 72234 ON CONFLICT (game_id, language_code) DO NOTHING;
