INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beached-ii', 169906, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tn3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scde8f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beached II', 'Whilst travelling out on the open sea, your boat sinks. You, and two others are washed onto a tropical island. The island is a paradise, with trees, bananas, coconuts, and vines. However, you suddenly remember the long range weather forecast. A tornado will form in this area in about one week. You must work hard to build a raft to get off the island, but also make sure you keep alive by eating, drinking and sleeping. The other survivors must build their own rafts too. You must decide if and when you help them, or if you line your own pockets with gold.' FROM games WHERE igdb_id = 169906 ON CONFLICT (game_id, language_code) DO NOTHING;
