INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Ultra NASCAR Pinball', '3-D Ultra NASCAR Pinball is, as the name suggests, a pinball game with a racing theme. Unique is that the theme is not only present on the table''s background images but that the player actually takes the role of one of four real-life NASCAR drivers. Every race consists of three parts, each represented by one table: preparing, racing and pit stops.' FROM games WHERE igdb_id = 50469 ON CONFLICT (game_id, language_code) DO NOTHING;
