INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Vengeance', 'Humans and elves had once lived together in peace, until many centuries ago when a renegade band of elves had challenged for power. Banished to underground caverns, they became known as the ''Dark Elves,'' and have been vowing revenge on the surface dwellers - a Dark Vengeance. A prophecy foretold of their return and the history of the tale was forced down, but after countless peaceful centuries the people of the land became fearless and ignored the ancient tales.' FROM games WHERE igdb_id = 51368 ON CONFLICT (game_id, language_code) DO NOTHING;
