INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shin-nippon-pro-wrestling-toukon-retsuden-3', 44802, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hg5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8cl5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Nippon Pro Wrestling: Toukon Retsuden 3', 'Shin Nihon Pro Wrestling - Toukon Retsuden 3 is the third and last sequel for the Playstation One console to one of the most popular wrestling games ever made. The game still maintained its wonderful polygon graphics, large range of moves, and smooth game control. The new game has all of the old favorite wrestlers, plus new wrestlers like Chris Benoit, Tiger Mask, and Antonio Inoki. Tag Team and Battle Royal modes have also been added. New moves, arenas, and new situation moves (like running tackles) have added to the game.' FROM games WHERE igdb_id = 44802 ON CONFLICT (game_id, language_code) DO NOTHING;
