INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic PC', 'Sonic PC is a fan game developed and released by Physik Multimedia in 1998, packed in with Sonic Klik & Play Collection. The game is currently only available in Sonic Klik & Play Collection, as the original game has yet to be found. It uses 32-bit conversion images of sprites from Sonic the Hedgehog CD and Sonic the Hedgehog 2, instead of the original 16-bit sprites.' FROM games WHERE igdb_id = 300013 ON CONFLICT (game_id, language_code) DO NOTHING;
