INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoshi no Oka Gakuen Monogatari: Gakuensai', 'Kazuya Murata, the main character, is transferred to a new school, in which he has to help organize the school festival that is one month away. In the meantime, he will also get along with the other students, as they all make sure to make the school festival a fun experience.' FROM games WHERE igdb_id = 325183 ON CONFLICT (game_id, language_code) DO NOTHING;
