INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Music: Music Creation for the PlayStation', 'In 1998, Codemasters and Jester Interactive created Music: Music Creation For The PlayStation―a video game that simulated an authentic music-making experience on the popular gaming console. Released solely for PlayStation, the music-making program provided gamers and music enthusiasts with 50 pre-recorded riffs and 300 sampled instruments to develop loops and mix them on a 16-track sequencer―along with an array of other audio editing options' FROM games WHERE igdb_id = 131289 ON CONFLICT (game_id, language_code) DO NOTHING;
