INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rami-chan no Ooedo Sugoroku: Keio Yuugeki-tai Gaiden', 'Rami-chan no Ooedo Sugoroku: Keio Yuugekitai Gaiden is a 1998 video game for the PlayStation. Developed by Victor Interactive Software, it is the third and last game in the Keio Flying Squadron series, and was released only in Japan. While the first game is a side-scrolling shoot ''em up and its sequel, Keio Flying Squadron 2, is a platformer with shooter sections, the third game is a party game. Like the first two games, the third game refers to Japanese culture, both ancient and modern simultaneously.' FROM games WHERE igdb_id = 66215 ON CONFLICT (game_id, language_code) DO NOTHING;
