INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Fighters R-1', 'The King of Fighters: R1 marks SNK''s first time bringing the KOF series onto a handheld... and what better system than their own Neo Geo Pocket to do just that? 14 of the most well known KOF characters make their appearance in KOF: R-1, along with some recognizable backgrounds and gameplay features based on The King of Fighters ''97. Players can choose from "Extra" & "Advance" play modes similar to KOF ''97, and most characters play closely to their original versions.' FROM games WHERE igdb_id = 47602 ON CONFLICT (game_id, language_code) DO NOTHING;
