INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheel of Fortune', 'The 1998 PC version of Wheel of Fortune is a computer game adaptation of the popular TV game show, developed by Hasbro Interactive. It allows players to experience the thrill of the show, solving word puzzles by spinning a wheel and guessing letters. The game includes over 2,000 puzzles, special prizes, multiple studio settings, and full-motion video featuring Vanna White. It offers both classic and tournament modes of play, accommodating one to three players.' FROM games WHERE igdb_id = 144230 ON CONFLICT (game_id, language_code) DO NOTHING;
