INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suzuki Alstare Extreme Racing', 'Suzuki Alstare Exteme Racing is a motorcycle racing game with the Suzuki license. It has two playing modes: time trial (single races against four to seven AI racers) and the championship which are 16 successive races on the 16 courses. At first there are only two motorbikes available, but successes in time trial mode unlock better ones to use in the championship. Also restricted is the number of available time trial courses; the rest also has to be unlocked first. The player can perform a wheelie which causes a considerate, temporary acceleration.' FROM games WHERE igdb_id = 24153 ON CONFLICT (game_id, language_code) DO NOTHING;
