INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starship Troopers: Battlespace', 'Starship Troopers: Battlespace was a massively multiplayer space shooter playable on the GameStorm network. Players could fight in campaigns or quick matches as the human Feds or the alien Arachnids, and battled live players from the opposing team. Points and victories contributed to persistently-tracked stats, resulting in regular promotions for skilled players.' FROM games WHERE igdb_id = 72724 ON CONFLICT (game_id, language_code) DO NOTHING;
