INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazon Trail 3rd Edition: Rainforest Adventures', 'Despite the title, Amazon Trail 3rd Edition: Rainforest Adventures is a remake of Amazon Trail II. The title was developed and published by The Learning Company, a company that specializes in educational software for children. An adventure title, the player navigates the Amazon River, and through time travel, meets several figures in history, and learns how their influence shapes the region today.' FROM games WHERE igdb_id = 69959 ON CONFLICT (game_id, language_code) DO NOTHING;
