INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Preschool', 'A game that focuses on preschool curriculum. It serves as an updated version of JumpStart Preschool (1995). In the game, the player can explore and play in an interactive schoolhouse which contains many activities in the classroom. The player is rewarded with train tickets for completing activities. When the player collects four train tickets, they can go on a magical train ride to one of ten different locations. After visiting a location, the player gets a stamp in their passport book.' FROM games WHERE igdb_id = 315521 ON CONFLICT (game_id, language_code) DO NOTHING;
