INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thinkin'' Things: Sky Island Mysteries', 'Solve Mysteries and Bring Order Back to the Sky Islands! Break out your logic, prioritization and decision-making skills—you’ll find hundreds of zany and absorbing challenges at the Sky Islands! The more problems you complete, the more clues you pick up for the mysteries. Then zip on over to Clue Central and help Detective Joe Cluestoe and his sidekick, Spike, identify who’s behind each daring deed.' FROM games WHERE igdb_id = 294510 ON CONFLICT (game_id, language_code) DO NOTHING;
