INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Sk8er', 'Take to the streets on one of ten stylin'' boards in the first skateboarding game for the PlayStation, courtesy of Electronic Arts and Micro Cabin. Two variations of play include the Street Tour Mode, where you skate through three 3D courses trying to pull off as many tricks as you can within a time limit, and Free Skate Mode, where you either play for points or practice your moves without worrying about the clock.' FROM games WHERE igdb_id = 22839 ON CONFLICT (game_id, language_code) DO NOTHING;
