INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vecmania', 46513, '1998-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vecmania', 'Vecmania has the largest amount of games for a homebrew compilation for the Vectrex, with a full seven games (one hidden) and two unfinished demos, being clones of the arcade games of Tempest, Star Wars, Missile Command, Space Invaders, Eliminator, Breakout, Discs Of Tron, Asteroids and Phoenix.  The games can be scrolled through at the main menu by moving the joystick or D-pad left and right and then chosen by pressing up on the joystick or D-pad. The main menu can be returned to by pressing three on the controller when the player is on an individual game''s title screen (except for the demos).  Games in Vecmania:  - Star Fire Spirits  - Repulse  - Vector Vaders Remix  - Patriots Remix  - Rockaroids Remix - 3rd Rock  - Disc Duel Demo  - Abyss Demo' FROM games WHERE igdb_id = 46513 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46513 AND p.igdb_id = 70 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pettson-o-findus-i-tradgarden', 70121, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co720k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjw7r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pettson o Findus i Trädgården', 'In this educational game for ages seven to twelve, you are Findus, the cat, who promises to look after Pettson''s garden, but does not have any tools. You walk around and play games to train your language skills, math skills and reflexes. After each successful game, you receive an object. The aim of the game is to collect a tools and free the gardener who is locked up in "Joke world" under Pettson''s house. The game has a humorous tone and all drawings are done by Sven Nordqvist. Each mini-game trains a skill and has various difficulties for each child.' FROM games WHERE igdb_id = 70121 ON CONFLICT (game_id, language_code) DO NOTHING;
