INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mitsumete Knight', 'Mitsumete Knight is a 1997 Dating Sim on PlayStation 1, developed by Konami in cooperation with Red Company. The spiritual successor of Konami''s smash hit Tokimeki Memorial: Forever with you, it uses the same game engine and most of its successful mechanics, but with several exciting twists!' FROM games WHERE igdb_id = 92966 ON CONFLICT (game_id, language_code) DO NOTHING;
