INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sequence Palladium', 'Released in 1998, Sequence Palladium is a fantasy mecha strategy RPG for Windows PC. The game follows a three part flow: starting with story events that into selecting a scenario which you then play out on the battle map and then continue to new story events. Mechs in Sequence Palladium (called Wizards in game) require a knight and para-sweet (spirits) to form a contract to pilot. A significant portion of character management in Sequence Palladium is nurturing the relationships between knights and para-sweets, and selecting optimal pairs. Combat is fought from a top down perspective, with an alternating player and enemy phase. All units are moved at once.' FROM games WHERE igdb_id = 246654 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 246654 AND ge.slug = 'turn-based-strategy-tbs' ON CONFLICT DO NOTHING;
