INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF War Zone', 'WWF WARZONE is here, featuring the top superstars in the World Wrestling Federation! Signature and finishing moves unique to each wrestler. Specialized matches including Steel Cage Match. Four-player action with Tag Team, Tornado, War, and Training Modes! Over 300 motion captured maneuvers. Create and save up to 30 customized wrestlers!' FROM games WHERE igdb_id = 3645 ON CONFLICT (game_id, language_code) DO NOTHING;
