INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Robo Blast', 'Sonic Robo Blast is an early Sonic fan game from 1998, created by Sonikku, real name Johnny Wallbank, of Sonic Team Junior. It is one of the earliest Sonic fangames to exist and led to the founding of Sonic Team Junior as well as the eventual creation of it''s sequel, Sonic Robo Blast 2.' FROM games WHERE igdb_id = 134011 ON CONFLICT (game_id, language_code) DO NOTHING;
