INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shichisei Toushin Guyferd: Crown Kaimetsu Sakusen', 'Shichisei Toushin Guyferd Crown Kaimetsu Sakusen is a game based on Seven Star Fighting God Guyferd, that was a Tokusatsu series made by Toho and Capcom, and aired on TV Tokyo in 1996. Guyferd borrows aspects from Bio Booster Armor Guyver and Fist of the North Star.' FROM games WHERE igdb_id = 229700 ON CONFLICT (game_id, language_code) DO NOTHING;
