INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tour Party: Sotsugyou Ryokou ni Ikou', 'Tour Party Sotsugyou Ryokou ni Ikou is a board game, that was released for Sega Saturn and PlayStation, in which the player can choose at the beginning of the game to play as a girl or a boy, the theme of the board is to travel, and the game features at the 4 human players to play as the same time and compete against the others. The gameplay is similar to Takara''s the Game of life but in Tour Party, during the journey the players will meet different people and they can become friends with them, and different events that will make the trip more interesting. The game features 8 different characters to choose from and a complete viewer mode with character profiles, musics, and other unlockables modes.' FROM games WHERE igdb_id = 203050 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 203050 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
