INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circuit Breakers', 'Prepare yourself for the fastest, most stomach churning racing game ever! Circuit Breakers is like no other racing game on Earth! Up to four players can battle head to head on over 30 roller coaster race tracks in a choice of 8 spectacular 3D worlds. No dull "corridor" racing, each track features hair-raising banked corners, heart-in-the-mouth jaw dropping dips and buttock-clenching drops -- all in spectacular 3D.' FROM games WHERE igdb_id = 135771 ON CONFLICT (game_id, language_code) DO NOTHING;
