INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Generation: Koi Ka? Shigoto Ka!?', 'Dream Generation: Koi ka? Shigoto ka!?... is a raising simulation & love adventure game. The player controls 19-year-old Toranosuke Rokujō, an aimless college student who has no idea what he wants out of life. After meeting up with a group of his high-school classmates, he decides it''s time to get his life in order, find a job, and find a girlfriend within the next year.' FROM games WHERE igdb_id = 130468 ON CONFLICT (game_id, language_code) DO NOTHING;
