INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PGA Tour Gold', 'If you have ever dreamed of stepping inside the ropes and walking up the fairway instead of watching from afar, then PGA TOUR Golf is the game for you. No tee times. No grees fees. Just you, the game''s greatest players and the world''s most magnificent golf courses. Play for fun or play to win. But the only way to play PEBBLE BEACH is to play PGA TOUR.' FROM games WHERE igdb_id = 69971 ON CONFLICT (game_id, language_code) DO NOTHING;
