INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beverly Hills Models', 'From the publishers of hit interactive CD-Rom titles "Exposed" and "Tabloid Beauties", MacDaddy Entertainment proudly presents "Beverly Hills Models." Photographed in some of Beverly Hill''s finest hotels, "Beverly Hills Models" offers 250 revealing photographs of MacDaddy''s most beautiful girls. Browsing through the coveted MacDaddy Photo Album, search for the perfect pose of Cindy. Glance at the enchanting Ashley, Cuddle with the loveable Jessica. Peek at the sultry Lana. Or become intimate with the unforgettable Gina. The choice is up to you.' FROM games WHERE igdb_id = 201264 ON CONFLICT (game_id, language_code) DO NOTHING;
