INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Techno Drive', 'Techno Drive is an arcade driving game that focuses on technical driving skills rather than speed. Players are tasked with completing a series of driving challenges designed to test precision, control, and reaction time. The game is notable for its futuristic, minimalist visual style with flat-shaded polygons and a techno soundtrack that complements its high-tech theme.' FROM games WHERE igdb_id = 319867 ON CONFLICT (game_id, language_code) DO NOTHING;
