INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Baron 3D', 'Red Baron 3-D is a World War I combat flight simulation, essentially a heavily patched version of Red Baron II. The game is playable as a single-player game in either campaign or instant mission mode, or in a multiplayer dogfight mode against up to 100 opponents via internet game matching services. Players can play as French, British, German or American pilots and can choose from 22 authentic WWI planes.' FROM games WHERE igdb_id = 50124 ON CONFLICT (game_id, language_code) DO NOTHING;
