INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Dragoon Saga', 'Enter the world of Panzer Dragoon Saga and experience a game like no other: a fusion of classic Panzer action with the most technologically advanced RPG to come to Saturn. Board your morphing dragon and behold as the mysteries of the Panzer world unfurl across four massive CDs. The new "rail free" 3D engine lets you soar deeper into role-playing adventure than you ever before imagined. Your destiny awaits.' FROM games WHERE igdb_id = 1671 ON CONFLICT (game_id, language_code) DO NOTHING;
