INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Flip Shot', 'Battle Flip Shot (sometimes also referred to simply as Flip Shot) is a 1998 ball-and-paddle game developed and published by Visco exclusively for the arcade cabinet known as the SNK Neo-Geo MVS hardware. It combines the genres of the Magnavox Odyssey Tennis game, Atari''s Pong and Breakout arcades, and Nintendo''s Spitball Sparky of the Game & Watch series. In 2001, Visco created and released Bang Bead, the follow-up to Battle Flip Shot.' FROM games WHERE igdb_id = 39667 ON CONFLICT (game_id, language_code) DO NOTHING;
