INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Frogger', 'Guide frogs across a busy street and then through dangerous water to get to their home, in this enhanced version of this arcade game clone by Christopher Salomon. The variety of objects and enemies will kill a players'' frog on contact, plus there is a timer for each level too, of which there are 16 total. The game is enhanced with a pause mode, so you can take a break if you need too!' FROM games WHERE igdb_id = 46517 ON CONFLICT (game_id, language_code) DO NOTHING;
