INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('friday-death-to-arthur-yahtzee', 62155, '1998-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pnz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccs24.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Friday: Death to Arthur Yahtzee', 'This is graphical point-and-click adventure with simple original engine. The game, like most 3rd Person adventure games, consists of action buttons which you use to interact with your surrounding. Simple as it is, it has your standard Look, Use, Talk, Inventory features. You are Arthur Yahtzee, a dole-bludger living in Los Angeles, who is credited with one major event - when the local Federal Research Institute started spawning hideous mutants, he single-handedly stopped them. Now, another branch of FRI in Chicago are spawning more mutants, and this time they''re after YOU...' FROM games WHERE igdb_id = 62155 ON CONFLICT (game_id, language_code) DO NOTHING;
