INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('daytona-usa-2-battle-on-the-edge', 39291, '1998-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tz6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sck6u1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA 2: Battle on the Edge', 'Daytona USA 2: Battle on the Edge is an arcade racing game released by Sega in 1998 as a follow-up to the extremely successful Daytona USA. The game featured vastly superior graphics, utilizing the Sega Model 3 hardware. The majority of Daytona USA 2 cabinets were released as deluxe models (with far fewer Twin Cabinets), which could be linked together for up to four players. A notable change from the original is that the player has the choice from multiple cars, each with varying capabilities for varying levels of player experience. Just like before, the game has three courses – a Beginner course with 8 laps, an Advanced course with 4 laps, and a long Expert course with 2 laps. The ''time lap'' mode also returns, and is accessed in the same manner – by holding down start at the transmission select screen. Like the original game, mirrored versions of the tracks can also be played by holding down the Start button when selecting the course. It is recommended, however, that the player has had mastery of the course beforehand. By request, an arcade operator could put the game on Grand Prix or Endurance mode to increase the number of laps in a game. Finishing a race in the top 3 in any course allows the player to view an "ending" and see the game credits.' FROM games WHERE igdb_id = 39291 ON CONFLICT (game_id, language_code) DO NOTHING;
