INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Segata Sanshirou Shinkenyugi', 'A collection of minigames based on the popular Japanese Saturn mascot Segata Sanshiro. Each game is based on a specific commercial and completing them unlocks the ability to view the related commercial. This title was released after the final Segata Sanshiro commercial ran, in which Segata risks his life to save the SEGA headquarters building from an oncoming missile.' FROM games WHERE igdb_id = 46049 ON CONFLICT (game_id, language_code) DO NOTHING;
