INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rent-A-Hero', 'Rent-a-Hero is a graphic adventure game developed by the Austrian studio Neo Software (later Rockstar Vienna) and published by Magic Bytes in 1998, and by SouthPeak Games in 2000. Rent-a-Hero is a traditional point-and-click adventure. The characters are modeled in 3D but the background graphics are pre-rendered. There are over 30 locations and over 30 characters to interact with. With its comic anachronisms and pirate theme, the game''s humour is similar to that of Monkey Island.' FROM games WHERE igdb_id = 6001 ON CONFLICT (game_id, language_code) DO NOTHING;
