INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Derby Stallion 98', 'The Derby Stallion (ダービースタリオン?) - also known in Japan by the portmanteau abbreviation DerbyStal (ダビスタ?) - video games are a series of genre-merging horse-racing and business simulation games originally created by ASCII Entertainment, and released by Nintendo. The series comprises 21 games, spans more than 10 console platforms, and is the best-selling horse racing series of all time with total sales topping more than 4 million in Japan.[1]' FROM games WHERE igdb_id = 38237 ON CONFLICT (game_id, language_code) DO NOTHING;
