INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 2: The Shogi', 'Shogi, also known as Japanese chess, is a two-player board game in the same family as Western chess, chaturanga, and Chinese Xiangqi, and is the most popular of a family of chess variants native to Japan. Shogi means general''s. Simple 1500 Series vol. 002 - The Shogi is a shogi game supervised by the president of the Computer Shogi Association, that features 3 difficulty levels and also a 2 players vs mode.' FROM games WHERE igdb_id = 70571 ON CONFLICT (game_id, language_code) DO NOTHING;
