INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iggy''s Reckin'' Balls', 'A vertical race up towering tracks. Iggy and the Reckin'' Balls are in the race of their lives. A winner-take-all dash to the top of twisted, looped, warped and genuinely demented courses! Smash, crash and swing with Iggy, his friends, plus loads of secret characters. Over 100 tracks, tons of shortcuts, secret paths, loops and elevators. One to four player racing action with Battle and Versus mode.' FROM games WHERE igdb_id = 3394 ON CONFLICT (game_id, language_code) DO NOTHING;
