INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giga Pets: Looney Tunes - Taz Mania', 'Giga Pets are digital pet toys. Available in a variety of different characters, each Giga Pet is a palm-sized unit with an LCD screen and attached key ring. To ensure a happy, healthy pet, its owner has to take care of it similar to how one might care for a real animal, including feeding, cleaning, and playing with their Giga Pet.' FROM games WHERE igdb_id = 218048 ON CONFLICT (game_id, language_code) DO NOTHING;
