INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roll Away', 'Roll Away is a 3D platform puzzle video game which places the player in control of a Kula beachball. The main objective of the game is to collect keys which unlock the level exits, as well as coins and jewels along the way. The game makes use of alternative physics, changing the direction of gravity as the ball moves.' FROM games WHERE igdb_id = 9678 ON CONFLICT (game_id, language_code) DO NOTHING;
