INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('waialae-country-club-true-golf-classics', 3627, '1998-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5p8r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc74sa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waialae Country Club: True Golf Classics', 'Grab your clubs and head for the first tee. This golf sim recreates the world famous Hawaiian Waialae Golf Course, noted for lots of bunkers and very fast greens. You can choose your golfer, assign him a caddy, pick your set of clubs and adjust the power, putting, technical, recovery and wind game stats to suit your personal preference. The game offers a practice training mode, a tournament mode and the ability to challenge your friends in a stroke match. Oddly, this game was not sanctioned by the PGA and assumes that the golfer is always male.' FROM games WHERE igdb_id = 3627 ON CONFLICT (game_id, language_code) DO NOTHING;
