INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vigilance', 'Vigilance is a third-person shooter that follows eight agents working for the counter-terrorist organization SION (Special Intelligence Operations Network). The game combines first and third person perspective, allowing the player to control one of eight agents each with varied strengths and weaknesses. Aside from the basic single player mode, it also came with a support of play over LAN and Heat.net.' FROM games WHERE igdb_id = 93480 ON CONFLICT (game_id, language_code) DO NOTHING;
