INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Video Time Machine', 'A lost homebrew out of "time", this useful utility cart by Chris Cracknell uses favorite classic characters racing across the screen to track the time (along with a digital display), turning your Atari and tv into a retro timepiece. On the half hour the happy chasing characters change, giving you a wide variety of icons to wile your time away looking at.' FROM games WHERE igdb_id = 40770 ON CONFLICT (game_id, language_code) DO NOTHING;
