INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 45012 AND rs.code = 'ESRB' AND r.code = 'T' ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animaniacs-ten-pin-alley', 19432, '1998-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7cqw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animaniacs: Ten Pin Alley', 'Animaniacs: Ten Pin Alley is a wacky take on the world of bowling. It includes ten different Animaniacs characters, including Yakko, Wakko, Dot and the Warner Brothers (and sister). The game features tons of new modes, taking off from the original Ten Pin Alley game for the PlayStation. There is a tournament mode, a team up mode, kids mode, and the typical exhibition mode, also known as open play. The action takes place on four completely new lanes, including the World Domination Stadium, Wacky Alley, Boogey Bowl, and Ten Pin Alley. Up to six players can compete in any of the games assorted modes, allowing for fun for the whole family.' FROM games WHERE igdb_id = 19432 ON CONFLICT (game_id, language_code) DO NOTHING;
