INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot', 'Crash Bandicoot is a licensed platform game developed and published by Tiger Electronics and published by Universal Interactive in North America, released on a handheld dedicated console in 1998. It is the third game released in the Crash Bandicoot series overall, the first to be released on a handheld console, and the first to feature a multiplayer option. Despite bearing the same name, the game is neither an adaptation nor port of the 1996 Crash Bandicoot game, featuring a distinct storyline and a set of levels of its own.' FROM games WHERE igdb_id = 210243 ON CONFLICT (game_id, language_code) DO NOTHING;
