INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stellar Assault SS', 'Stellar Assault SS is a Sega Saturn space combat simulator game developed and published by SIMS. An enhanced port of the titular 1995 Sega CS game Stellar Assault, it was released exclusively in Japan in February 1998. Like its predecessor, Stellar Assault SS is a "dogfight" shooter set in outer space, featuring first- and third-person viewpoints. While the core gameplay remains much the same, Stellar Assault SS is more story-driven, with support characters and voice acting. Ships and environments are also texture-mapped, while some levels take place on planets.' FROM games WHERE igdb_id = 112045 ON CONFLICT (game_id, language_code) DO NOTHING;
