INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jeff-waynes-the-war-of-the-worlds--1', 129581, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zb1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuz9s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeff Wayne''s The War of the Worlds', 'The game based on Jeff Wayne''s musical play and the classic science fiction novel by H.G. Wells. it is the year 1898 and the Martian have escaped from their dying homeworld to conquer the Earth and take its resources - and the blood of its inhabitants. Take either side in this epic real-time strategy game. You can play as the Martians with their superior technology and powerful but expensive war machines in their campaign to take over Great Britain and the rest of the world. Or play as the weaker but more numerous Humans to turn back the alien onslaught before their fiendish plans can be made reality. Jeff Wayne''s The War of the Worlds is a real-time strategy game. There aren''t any set missions or a linear story-line, it''s all up to you. You must use your time wisely to build up your forces and production facilities within your sectors before the enemy can launch their attack. Research new technologies, construct new buildings, and build new military units to win the game and save your race. The fate of your species, whether Human or Martian, is on the line.' FROM games WHERE igdb_id = 129581 ON CONFLICT (game_id, language_code) DO NOTHING;
