INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zootto Mahjong!', 'Zoo-tto Mahjong! is a Nintendo developed and published Super Famicom video game. It was released on July 1, 1998. It is a simple game of Mahjong, of which there were many that were created by Nintendo. It was the last Mahjong game developed for the Super Famicom, and a preview version was also available through Satellaview. In the game you choose which animal you want to play as before the game starts.' FROM games WHERE igdb_id = 37744 ON CONFLICT (game_id, language_code) DO NOTHING;
