INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suikoden II', 'Experience An Epic Tale of Warfare, Magic, Friendship And Betrayal -New tactical map battles add a whole level of strategy -Fantastic spells with stunning animation sequences and specialized attacks -Over 108 different characters can join your party and help you on your quest -Unlock hidden storylines using your memory card data from the original Suikoden -Build up your castle during the game to a thriving virtual community' FROM games WHERE igdb_id = 1454 ON CONFLICT (game_id, language_code) DO NOTHING;
