INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gex-enter-the-gecko', 3506, '1998-02-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q8n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lfg7im3h9pylrsjpmzrm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gex: Enter the Gecko', '"Is it just me, or am I engulfed in flames?" is one of the many one-liners uttered by Gex, a wise cracking gecko who should check himself into television rehab; he''s addicted to it. After saving the Television Realm from the evil Rez in his first adventure, the gecko was ready to kick back, relax, and watch a little television. Little did he know his adventure was just beginning. One day, two secret agent goons showed up at Gex''s doorstep. They inform him that Rez is back and looking for vengeance; the evil monster is planning to destroy the Television Realm once more...and possibly the world. When Gex tells them that he''s retired and doesn''t care, one of the goons hits the gecko on the head and takes him to a secluded place. When Gex comes to, the mystery men plead with the gecko to take the cash and help destroy Rez for good...or at least make him disappear. With that incentive (the cash), the wise cracking lizard slips into his special agent suit and plunges headfirst into the Television Realm. Watch out, Rez -- Gex is back!' FROM games WHERE igdb_id = 3506 ON CONFLICT (game_id, language_code) DO NOTHING;
