INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Truck Adventure', 'Magical Truck Adventure gives the player the feel of actually riding a rail car. An action-pedal and truck lever assists the player in chasing, jumping, and dodging the evil villains that threaten to steal Alma''s precious stone. All this excitement takes place on a railroad track with 6 amazingly detailed scenic routes. The 3 challenging stages include an array of obstacles, wild rhino''s, hungry crocodiles, and speeding trains to name a few.' FROM games WHERE igdb_id = 39477 ON CONFLICT (game_id, language_code) DO NOTHING;
