INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-com-interceptor', 27, '1998-06-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cpk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4upb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-COM: Interceptor', 'They''re back...only this time the heinous aliens are out to destroy Earth and rule the new frontier. As X-COM commander, it''s your sole duty to protect humanity and the prized mining operations in outer space. You must strategically equip your X-COM fighters, amass a formidable arsenal and then fulfill your mandate by going head-to-head with the devious element. The action is fast. And the opposing forces are wicked. But if you are smart, diligent and quick, you will prevail in a masterfully fought campaign to save our planet from perilous collapse.' FROM games WHERE igdb_id = 27 ON CONFLICT (game_id, language_code) DO NOTHING;
