INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('speed-busters-american-highways', 46531, '1998-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tud.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rzomqzdvb8mfwxfvxb5d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Busters: American Highways', 'For centuries, the speed limit on American highways has been restricted by law. Technology now offers drivers the chance to make their own choice in the virtual world with Speed Busters: American Highways. The police have lost their minds and reward the fastest players to fly past their strategically placed radar! Earn cash to upgrade one of eight specially designed vehicles based on models ranging from the ‘50s to the ‘90s. Tackle mixed terrain, avoid shocking animations, and storm through environments based on real North American locations. High stakes gambling & custom car racing through Satan’s playground! Race through crowded cities, snow-covered mountains, and active volcanoes. Take on UFOs, rock slides, fire-breathing dinosaurs, and a giant fist-smashing ape! Challenge 17 diabolical drivers through championships, vendettas, and high-stakes duels. Tons of alternative routes – can you find them all?' FROM games WHERE igdb_id = 46531 ON CONFLICT (game_id, language_code) DO NOTHING;
